#!/usr/bin/env python3
"""Run a command in a pty, send keys with delays, capture raw output. Emulates cursor for DSR."""
import os, pty, sys, time, select, termios, struct, fcntl, signal, re, unicodedata

def wcwidth(ch):
    if unicodedata.combining(ch): return 0
    ea = unicodedata.east_asian_width(ch)
    if ea in ('W', 'F'): return 2
    if ord(ch) < 32 or ord(ch) == 0x7f: return 0
    return 1

class Term:
    def __init__(self, rows, cols):
        self.rows, self.cols = rows, cols
        self.r, self.c = 0, 0  # 0-indexed
        self.saved = (0, 0)
        self.pending_wrap = False
        self.buf = b""
        self.responses = []
    def feed(self, data):
        self.buf += data
        out = []
        i = 0
        b = self.buf
        while i < len(b):
            ch = b[i]
            if ch == 0x1b:
                if i + 1 >= len(b):
                    break  # incomplete
                nxt = b[i+1]
                if nxt == ord('['):
                    m = re.match(rb'\x1b\[([?>!]?)([0-9;]*)([@-~])', b[i:])
                    if not m:
                        if len(b) - i > 32: i += 1; continue
                        break
                    priv, params, final = m.group(1), m.group(2), m.group(3)
                    self.csi(priv, params, final)
                    i += m.end()
                    continue
                elif nxt == ord(']'):
                    # OSC ... terminated by BEL or ST
                    m = re.match(rb'\x1b\].*?(\x07|\x1b\\)', b[i:], re.S)
                    if not m: break
                    i += m.end(); continue
                else:
                    # ESC x
                    if nxt == ord('7'): self.saved = (self.r, self.c)
                    elif nxt == ord('8'): self.r, self.c = self.saved; self.pending_wrap = False
                    i += 2; continue
            elif ch == 0x0d:
                self.c = 0; self.pending_wrap = False; i += 1
            elif ch == 0x0a:
                if self.r < self.rows - 1: self.r += 1
                self.pending_wrap = False; i += 1
            elif ch == 0x08:
                if self.c > 0: self.c -= 1
                self.pending_wrap = False; i += 1
            elif ch < 0x20 or ch == 0x7f:
                i += 1
            else:
                # decode one utf-8 char
                n = 1
                if ch >= 0xf0: n = 4
                elif ch >= 0xe0: n = 3
                elif ch >= 0xc0: n = 2
                if i + n > len(b): break
                try:
                    s = b[i:i+n].decode('utf-8')
                except Exception:
                    s = '?'
                w = wcwidth(s)
                if w > 0:
                    if self.pending_wrap:
                        self.c = 0
                        if self.r < self.rows - 1: self.r += 1
                        self.pending_wrap = False
                    self.c += w
                    if self.c >= self.cols:
                        self.c = self.cols - 1
                        self.pending_wrap = True
                i += n
        self.buf = b[i:]
        resp = self.responses; self.responses = []
        return resp
    def csi(self, priv, params, final):
        p = [int(x) if x else 0 for x in params.split(b';')] if params else []
        def P(k, d=1):
            return p[k] if k < len(p) and p[k] != 0 else d
        self.pending_wrap = False
        if priv == b'?':
            if params == b'1049':
                if final == b'h': self.saved = (self.r, self.c)
                else: self.r, self.c = self.saved
            return
        if final == b'H' or final == b'f':
            self.r = min(max(P(0) - 1, 0), self.rows - 1)
            self.c = min(max(P(1) - 1, 0), self.cols - 1)
        elif final == b'A': self.r = max(self.r - P(0), 0)
        elif final == b'B': self.r = min(self.r + P(0), self.rows - 1)
        elif final == b'C': self.c = min(self.c + P(0), self.cols - 1)
        elif final == b'D': self.c = max(self.c - P(0), 0)
        elif final == b'G': self.c = min(max(P(0) - 1, 0), self.cols - 1)
        elif final == b'd': self.r = min(max(P(0) - 1, 0), self.rows - 1)
        elif final == b'n' and params == b'6':
            self.responses.append(b'\x1b[%d;%dR' % (self.r + 1, self.c + 1))

def run(cmd, keys, cols=100, rows=30, cwd=None, env=None, timeout=0.5, final_wait=0.5):
    pid, fd = pty.fork()
    if pid == 0:
        if cwd: os.chdir(cwd)
        if env:
            for k,v in env.items():
                if v is None: os.environ.pop(k, None)
                else: os.environ[k] = v
        os.execvp(cmd[0], cmd)
    winsz = struct.pack("HHHH", rows, cols, 0, 0)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, winsz)
    term = Term(rows, cols)
    out = b""
    chunks = []
    alive = [True]
    def read_all(t):
        nonlocal out
        end = time.time() + t
        buf = b""
        while True:
            rem = end - time.time()
            if rem <= 0: break
            r,_,_ = select.select([fd],[],[],rem)
            if fd in r:
                try:
                    d = os.read(fd, 65536)
                except OSError:
                    alive[0] = False
                    break
                if not d: alive[0] = False; break
                buf += d
                for resp in term.feed(d):
                    os.write(fd, resp)
        out += buf
        return buf
    chunks.append(("<start>", read_all(timeout)))
    for k in keys:
        if isinstance(k, (int,float)):
