            os.write(fd, k if isinstance(k, bytes) else k.encode())
        except OSError:
            break
        chunks.append((k, read_all(timeout)))
    chunks.append(("<final>", read_all(final_wait)))
    status = None
    try:
        pid2, status = os.waitpid(pid, os.WNOHANG)
        if pid2 == 0:
            os.kill(pid, signal.SIGKILL); os.waitpid(pid, 0); status = None
    except Exception: pass
    return out, chunks, status

if __name__ == "__main__":
    import argparse
    ap = argparse.ArgumentParser()
    ap.add_argument("--cols", type=int, default=100)
    ap.add_argument("--rows", type=int, default=30)
    ap.add_argument("--cwd", default=None)
    ap.add_argument("--timeout", type=float, default=0.4)
    ap.add_argument("--out", default=None)
    ap.add_argument("--exe", default="/workspace/executable")
    ap.add_argument("--args", default="")
