use std::fmt;

#[derive(Debug)]
pub enum FxError {
    Io(String),
    Dirs(String),
    GetItem,
    OpenItem(String),
    OpenNewWindow(String),
    Yaml(String),
    Encode,
    PutItem(std::path::PathBuf),
    RemoveItem(std::path::PathBuf),
    TooSmallWindowSize,
    TerminalSizeDetection,
    Log(String),
    Unpack(String),
    InappropriateFileType,
    UnknownFileType,
    InvalidPath,
    DefaultEditor,
    NoExecConfig,
    Zoxide(String),
    Panic,
    Shell,
    Rename,
    Message(String),
}

impl fmt::Display for FxError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let s = match self {
            FxError::Io(s) => s.to_owned(),
            FxError::Dirs(s) => s.to_owned(),
            FxError::GetItem => "Error: Cannot get item info".to_owned(),
            FxError::OpenItem(s) => s.to_owned(),
            FxError::OpenNewWindow(s) => s.to_owned(),
            FxError::Yaml(s) => s.to_owned(),
            FxError::Encode => "Error: Incorrect encoding".to_owned(),
            FxError::PutItem(p) => format!("Error: Cannot copy -> {:?}", p),
            FxError::RemoveItem(p) => format!("Error: Cannot remove -> {:?}", p),
            FxError::TooSmallWindowSize => "Error: Too small window size".to_owned(),
            FxError::TerminalSizeDetection => "Error: Cannot detect terminal size".to_owned(),
            FxError::Log(s) => s.to_owned(),
            FxError::Unpack(s) => s.to_owned(),
            FxError::InappropriateFileType => "Seems not an archive file.".to_owned(),
            FxError::UnknownFileType => "Unknown file type".to_owned(),
            FxError::InvalidPath => "Path does not exist.".to_owned(),
            FxError::DefaultEditor => {
                "$EDITOR may not be set, or config file may be invalid.".to_owned()
            }
            FxError::NoExecConfig => "No exec configuration".to_owned(),
            FxError::Zoxide(s) => s.to_owned(),
            FxError::Panic => "Error: felix panicked".to_owned(),
            FxError::Shell => "Shell integration may not be configured.".to_owned(),
            FxError::Rename => "Error: Cannot rename".to_owned(),
            FxError::Message(s) => s.to_owned(),
        };
        write!(f, "{}", s)
    }
}

impl std::error::Error for FxError {}

impl From<std::io::Error> for FxError {
    fn from(e: std::io::Error) -> Self {
        FxError::Io(e.to_string())
    }
}

impl From<serde_yaml::Error> for FxError {
    fn from(e: serde_yaml::Error) -> Self {
        FxError::Yaml(e.to_string())
    }
}

impl From<std::string::FromUtf8Error> for FxError {
    fn from(_: std::string::FromUtf8Error) -> Self {
        FxError::Encode
    }
}

impl From<log::SetLoggerError> for FxError {
    fn from(e: log::SetLoggerError) -> Self {
        FxError::Log(e.to_string())
    }
}
