cat > term.rs <<'EOF'
use crossterm::cursor::{Hide, MoveLeft, MoveTo, Show};
use crossterm::style::{Color, ResetColor, SetBackgroundColor, SetForegroundColor};
use crossterm::terminal::{Clear, ClearType};
use crossterm::{execute, queue};
use std::io::{stdout, Write};

pub const INFO_ROW: u16 = 1;

pub fn flush() {
    let _ = stdout().flush();
}

pub fn move_to(x: u16, y: u16) {
    let _ = execute!(stdout(), MoveTo(x, y));
}

pub fn move_left(n: u16) {
    let _ = execute!(stdout(), MoveLeft(n));
}

pub fn clear_current_line() {
    let _ = execute!(stdout(), Clear(ClearType::CurrentLine));
}

pub fn clear_until_newline() {
    let _ = execute!(stdout(), Clear(ClearType::UntilNewLine));
}

pub fn clear_all() {
    let _ = execute!(stdout(), Clear(ClearType::All));
}

pub fn hide_cursor() {
    let _ = execute!(stdout(), Hide);
}

pub fn show_cursor() {
    let _ = execute!(stdout(), Show);
}

pub fn set_color(fg: Option<Color>, bg: Option<Color>) {
    let mut out = stdout();
    if let Some(c) = fg {
        let _ = queue!(out, SetForegroundColor(c));
    }
    if let Some(c) = bg {
        let _ = queue!(out, SetBackgroundColor(c));
    }
    let _ = out.flush();
}

pub fn reset_color() {
    let _ = execute!(stdout(), ResetColor);
}

pub fn print(s: &str) {
    let mut out = stdout();
    let _ = out.write_all(s.as_bytes());
    let _ = out.flush();
}

/// Print " " at the current cursor position and move left: erase the cursor mark.
pub fn delete_cursor() {
    print(" ");
    move_left(1);
}

/// Print the cursor mark ">" at the row `y`.
pub fn print_pointer(y: u16) {
    move_to(0, y);
    print(">");
    move_left(1);
}

/// Print a message on the info row.
pub fn print_info<T: std::fmt::Display>(message: T, then: u16) {
    delete_cursor();
    move_to(1, INFO_ROW);
    clear_current_line();
    print(&format!("{}", message));
    hide_cursor();
    print_pointer(then);
}

/// Print a warning (red background) on the info row.
pub fn print_warning<T: std::fmt::Display>(message: T, then: u16) {
    delete_cursor();
    move_to(1, INFO_ROW);
    clear_current_line();
    set_color(Some(Color::Grey), Some(Color::Red));
    print(&format!("{}", message));
    reset_color();
    hide_cursor();
    print_pointer(then);
}

/// Print the progress of operations like "1/3".
pub fn print_process<T: std::fmt::Display>(message: T) {
    delete_cursor();
    move_to(1, INFO_ROW);
    clear_current_line();
    print(&format!("{}", message));
}

/// Return the terminal size (columns, rows).
pub fn terminal_size() -> Option<(u16, u16)> {
    crossterm::terminal::size().ok()
}

/// Query the cursor position (column, row).
pub fn cursor_pos() -> std::io::Result<(u16, u16)> {
    crossterm::cursor::position()
}
EOF
echo ok"}

