                Split::Horizontal => {
                    let half = row / 2;
                    self.terminal_column = column;
                    self.terminal_row = half;
                    let (time_start, name_max) = make_layout(column);
                    self.time_start_pos = time_start;
                    self.name_max_len = name_max;
                    self.preview_start = (0, half + 1);
                    self.preview_space = (column, row - half - 2);
                }
