        let skip = self.nums.skip as usize;
        let end = self.terminal_row.saturating_sub(STARTING_POINT) as usize + skip;
        let mut row = BEGINNING_ROW;
        for (i, item) in list.iter().enumerate() {
            if i < skip {
                continue;
            }
            if i >= end {
                break;
            }
            move_to(SPACES, row);
            self.print_item(item, keyword);
            row += 1;
        }
    }

