#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PreviewType {
    TooBigSize,
    Directory,
    Image,
    Text,
    Binary,
}

/// Return (time_start_pos, name_max_len) for the given column width.
pub fn make_layout(column: u16) -> (u16, usize) {
    if column < PROPER_WIDTH {
        (column, (column.saturating_sub(SPACES)) as usize)
    } else {
        let time_start = column - TIME_WIDTH - 1;
        (time_start, (time_start - SPACES) as usize)
    }
}

/// Cut the string so that its display width does not exceed `width`.
pub fn cut_str_to_width(s: &str, width: usize) -> String {
    if s.width() <= width {
        return s.to_owned();
    }
    let mut result = String::new();
    let mut w = 0;
    for c in s.chars() {
        let cw = c.width().unwrap_or(0);
        if w + cw > width {
            break;
        }
        w += cw;
        result.push(c);
    }
    result
}

/// List the contents of a directory for the preview.
pub fn list_dir_contents(p: &Path) -> Vec<String> {
    let mut dirs = vec![];
    let mut files = vec![];
    if let Ok(rd) = std::fs::read_dir(p) {
        for entry in rd.flatten() {
            let name = entry.file_name().to_string_lossy().into_owned();
            let is_dir = entry
                .file_type()
                .map(|t| t.is_dir())
                .unwrap_or(false);
            if is_dir {
                dirs.push(name);
            } else {
                files.push(name);
            }
        }
    }
    dirs.sort_by(|a, b| natural_compare(a, b));
    files.sort_by(|a, b| natural_compare(a, b));
    let mut all: Vec<String> = dirs;
    all.append(&mut files);
    let len = all.len();
    all.into_iter()
        .enumerate()
        .map(|(i, name)| {
            if i == len - 1 {
                format!("└ {}", name)
            } else {
                format!("├ {}", name)
            }
        })
        .collect()
}
