pub struct PutFiles {
    pub original: Vec<PathBuf>,
    pub put: Vec<PathBuf>,
    pub dir: PathBuf,
}

#[derive(Debug, Clone)]
pub struct RenamedFile {
    pub original_name: PathBuf,
    pub new_name: PathBuf,
}

#[derive(Debug, Clone, Default)]
pub struct Operation {
    pub pos: usize,
    pub op_list: Vec<OpKind>,
}

impl Operation {
    pub fn branch(&mut self) {
        if self.pos > 0 {
            let len = self.op_list.len();
            self.op_list.truncate(len.saturating_sub(self.pos));
            self.pos = 0;
        }
    }
    pub fn push(&mut self, op: OpKind) {
        self.op_list.push(op);
    }
}

pub fn relog(op: &OpKind, undo: bool) {
    let mut result = if undo {
        "UNDO: ".to_owned()
    } else {
        "REDO: ".to_owned()
    };
    match op {
        OpKind::Put(op) => {
            result.push_str("PUT ");
            for x in &op.put {
                result.push_str(x.to_str().unwrap_or(""));
                result.push(' ');
            }
        }
        OpKind::Delete(op) => {
            result.push_str("DELETE ");
            for x in &op.original {
                result.push_str(x.to_str().unwrap_or(""));
                result.push(' ');
            }
        }
        OpKind::Rename(op) => {
            result.push_str("RENAME ");
            result.push_str(op.original_name.to_str().unwrap_or(""));
            result.push_str(" -> ");
            result.push_str(op.new_name.to_str().unwrap_or(""));
        }
    }
    log::info!("{}", result);
}
