use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Default)]
pub struct JumpList {
    pub list: Vec<PathBuf>,
    pub pos: usize,
}

impl JumpList {
    pub fn new(initial: &Path) -> Self {
        JumpList {
            list: vec![initial.to_path_buf()],
            pos: 0,
        }
    }

    /// Add a new path; truncate the forward history.
    pub fn add(&mut self, p: &Path) {
        self.list.truncate(self.pos + 1);
        self.list.push(p.to_path_buf());
        self.pos = self.list.len() - 1;
    }

    pub fn backward(&mut self) -> Option<PathBuf> {
        if self.pos == 0 {
            None
        } else {
            self.pos -= 1;
            self.list.get(self.pos).cloned()
        }
    }

    pub fn forward(&mut self) -> Option<PathBuf> {
        if self.pos + 1 >= self.list.len() {
            None
        } else {
            self.pos += 1;
            self.list.get(self.pos).cloned()
        }
    }
}
