#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FileType {
    Directory,
    File,
    Symlink,
}

#[derive(Debug, Clone)]
pub struct ItemInfo {
    pub file_type: FileType,
    pub file_name: String,
    pub file_path: PathBuf,
    pub symlink_dir_path: Option<PathBuf>,
    pub symlink_target: Option<PathBuf>,
    pub file_size: u64,
    pub file_ext: Option<String>,
    pub modified: Option<SystemTime>,
    pub is_hidden: bool,
    pub selected: bool,
    pub matches: bool,
    pub preview_type: Option<PreviewType>,
    pub content: Option<String>,
    pub permissions: Option<u32>,
    pub is_dir: bool,
}

#[derive(Debug, Clone)]
pub struct Memo {
    pub num: Num,
    pub cursor_pos: u16,
}

#[derive(Debug, Clone, Default)]
pub struct Registers {
    pub unnamed: Vec<ItemBuffer>,
    pub zero: Vec<ItemBuffer>,
    pub numbered: std::collections::VecDeque<Vec<ItemBuffer>>,
    pub named: BTreeMap<char, Vec<ItemBuffer>>,
}

#[derive(Debug, Clone)]
pub struct ItemBuffer {
    pub file_type: FileType,
    pub file_name: String,
    pub file_path: PathBuf,
}

impl ItemBuffer {
    pub fn new(item: &ItemInfo) -> Self {
        ItemBuffer {
            file_type: item.file_type,
            file_name: item.file_name.clone(),
            file_path: item.file_path.clone(),
        }
    }
}

impl Registers {
    /// Lines for the registers panel.
    pub fn prepare_reg(&self) -> Vec<String> {
        let mut lines = vec![];
        if !self.unnamed.is_empty() {
            lines.push(format!("\"\" {}", join_names(&self.unnamed)));
        }
        if !self.zero.is_empty() {
            lines.push(format!("\"0 {}", join_names(&self.zero)));
        }
        for (i, reg) in self.numbered.iter().enumerate() {
            if !reg.is_empty() {
                lines.push(format!("\"{} {}", i + 1, join_names(reg)));
            }
        }
        for (c, reg) in self.named.iter() {
            if !reg.is_empty() {
                lines.push(format!("\"{} {}", c, join_names(reg)));
            }
        }
        lines
    }

    /// Yank items: set "0 and "".
    pub fn yank_item(&mut self, items: Vec<ItemBuffer>) {
        self.zero = items.clone();
        self.unnamed = items;
    }

    /// Delete items: shift numbered registers and set "1 and "".
    pub fn delete_item(&mut self, items: Vec<ItemBuffer>) {
        self.numbered.push_front(items.clone());
        self.numbered.truncate(9);
        self.unnamed = items;
    }

    pub fn set_named(&mut self, c: char, items: Vec<ItemBuffer>) {
        self.unnamed = items.clone();
        self.named.insert(c, items);
    }

    pub fn append_named(&mut self, c: char, items: Vec<ItemBuffer>) {
        let entry = self.named.entry(c).or_default();
        entry.extend(items);
        self.unnamed = entry.clone();
    }

    pub fn get(&self, c: char) -> Option<Vec<ItemBuffer>> {
        match c {
            '"' => Some(self.unnamed.clone()),
            '0' => Some(self.zero.clone()),
            '1'..='9' => {
                let i = c.to_digit(10).unwrap() as usize - 1;
                self.numbered.get(i).cloned()
            }
            'a'..='z' => self.named.get(&c).cloned(),
            'A'..='Z' => self
                .named
                .get(&c.to_ascii_lowercase())
                .cloned(),
            _ => None,
        }
    }
}

fn join_names(items: &[ItemBuffer]) -> String {
    items
        .iter()
        .map(|x| x.file_name.clone())
        .collect::<Vec<String>>()
        .join(" ")
}

#[derive(Debug)]
pub struct State {
    pub list: Vec<ItemInfo>,
    pub current_dir: PathBuf,
    pub trash_dir: PathBuf,
    pub lwd_file: Option<PathBuf>,
    pub match_vim_exit_behavior: bool,
    pub ignore_case: bool,
    pub has_zoxide: bool,
    pub default: Option<String>,
    pub commands: Option<BTreeMap<String, String>>,
    pub registers: Registers,
    pub operations: Operation,
    pub jumplist: JumpList,
    pub c_memo: HashMap<PathBuf, Memo>,
    pub p_memo: HashMap<PathBuf, Memo>,
    pub keyword: Option<String>,
    pub layout: Layout,
    pub v_start: Option<usize>,
    pub is_ro: bool,
}

impl State {
    pub fn new(
        config: &Config,
        session: &Session,
        column: u16,
        row: u16,
        current_dir: PathBuf,
        trash_dir: PathBuf,
        lwd_file: Option<PathBuf>,
    ) -> State {
        let colors = config.color.clone().unwrap_or_default();
        let commands = config.exec.as_ref().map(|m| {
            let mut result = BTreeMap::new();
            for (cmd, exts) in m {
                for ext in exts {
                    result.insert(ext.clone(), cmd.clone());
                }
            }
            result
        });
        let side = match session.preview {
            Some(true) => Side::Preview,
            _ => Side::None,
        };
        let split = session.split.unwrap_or(Split::Vertical);
        let mut layout = Layout {
            nums: Num::new(),
            y: BEGINNING_ROW,
            terminal_row: row,
            terminal_column: column,
            name_max_len: 0,
            time_start_pos: 0,
            colors: ConfigColor {
                dir_fg: colors.dir_fg,
                file_fg: colors.file_fg,
                symlink_fg: colors.symlink_fg,
                dirty_fg: colors.dirty_fg,
            },
            sort_by: session.sort_by,
            show_hidden: session.show_hidden,
            side,
            split,
            preview_start: (0, 0),
            preview_space: (0, 0),
            preview_scroll: 0,
            has_chafa: false,
            is_kitty: false,
        };
        layout.update_size(column, row);
        State {
            list: vec![],
            current_dir: current_dir.clone(),
            trash_dir,
            lwd_file,
            match_vim_exit_behavior: config.match_vim_exit_behavior.unwrap_or(false),
            ignore_case: config.ignore_case.unwrap_or(false),
            has_zoxide: false,
            default: config.default.clone(),
            commands,
            registers: Registers::default(),
            operations: Operation::default(),
            jumplist: JumpList::new(&current_dir),
            c_memo: HashMap::new(),
            p_memo: HashMap::new(),
            keyword: None,
            layout,
            v_start: None,
            is_ro: false,
        }
    }

    /// Refresh the terminal size in the layout.
    pub fn refresh(&mut self, column: u16, row: u16) {
        self.layout.update_size(column, row);
    }

    // ---------- items ----------

    /// Read the current directory and build the item list.
    pub fn update_list(&mut self) -> Result<(), FxError> {
        let mut items = vec![];
        for entry in fs::read_dir(&self.current_dir)? {
            let entry = entry?;
            let item = make_item(&entry);
            if self.layout.show_hidden || !item.is_hidden {
                items.push(item);
            }
        }
        match self.layout.sort_by {
            SortKey::Name => items.sort_by(|a, b| natural_compare(&a.file_name, &b.file_name)),
            SortKey::Time => items.sort_by(|a, b| {
                time_secs(&b.modified).cmp(&time_secs(&a.modified))
            }),
        }
        let mut dirs: Vec<ItemInfo> = vec![];
        let mut files: Vec<ItemInfo> = vec![];
        for item in items {
            if item.is_dir {
                dirs.push(item);
            } else {
                files.push(item);
            }
        }
        dirs.append(&mut files);
        self.list = dirs;
        self.update_matches();
        Ok(())
    }

    /// Sort the list by the current key (used when toggling sort key).
    pub fn sort_items(&mut self) {
        match self.layout.sort_by {
            SortKey::Name => self
                .list
                .sort_by(|a, b| natural_compare(&a.file_name, &b.file_name)),
            SortKey::Time => self.list.sort_by(|a, b| {
                time_secs(&b.modified).cmp(&time_secs(&a.modified))
            }),
        }
        let mut dirs: Vec<ItemInfo> = vec![];
        let mut files: Vec<ItemInfo> = vec![];
        for item in self.list.drain(..) {
            if item.file_type == FileType::Directory {
                dirs.push(item);
            } else {
                files.push(item);
            }
        }
        dirs.append(&mut files);
        self.list = dirs;
    }

    /// Update `matches` flags according to the keyword.
    pub fn update_matches(&mut self) {
        let keyword = self.keyword.clone();
        let ignore_case = self.ignore_case;
        for item in self.list.iter_mut() {
            item.matches = match &keyword {
                Some(k) if !k.is_empty() => {
                    if ignore_case {
                        item.file_name.to_lowercase().contains(&k.to_lowercase())
                    } else {
                        item.file_name.contains(k.as_str())
                    }
                }
                _ => false,
            };
        }
    }

    pub fn get_item(&self) -> Result<&ItemInfo, FxError> {
        self.list.get(self.layout.nums.index).ok_or(FxError::GetItem)
    }

    pub fn get_item_mut(&mut self) -> Result<&mut ItemInfo, FxError> {
        self.list
            .get_mut(self.layout.nums.index)
            .ok_or(FxError::GetItem)
    }

    // ---------- drawing ----------

    pub fn clear_and_show_headline(&self) {
        clear_all();
        self.layout.print_header(&self.current_dir);
    }

    pub fn list_up(&self) {
        self.layout.list_up(&self.list, &self.keyword);
    }

    /// Erase the old cursor mark, print the footer (and side panel), print the cursor mark.
    pub fn move_cursor(&mut self, y: u16) {
        delete_cursor();
        let search_mode = self.search_result_shown;
        match self.layout.side {
            Side::Reg => {
                let lines = self.registers.prepare_reg();
                self.layout.print_registers(&lines);
                self.layout
                    .print_footer(&self.list, &self.keyword, search_mode);
            }
            Side::Preview => {
                self.layout
                    .print_footer(&self.list, &self.keyword, search_mode);
                if let Some(item) = self.list.get(self.layout.nums.index) {
                    let item = item.clone();
                    self.layout.print_preview(&item, y);
                }
            }
            Side::None => {
                self.layout
                    .print_footer(&self.list, &self.keyword, search_mode);
            }
        }
        print_pointer(y);
        self.layout.y = y;
    }

    pub fn redraw(&mut self, y: u16) {
        self.prepare_previews();
        self.clear_and_show_headline();
        self.list_up();
        self.move_cursor(y);
    }

    pub fn reload(&mut self, y: u16) -> Result<(), FxError> {
        self.update_list()?;
        self.clear_and_show_headline();
        self.list_up();
        self.move_cursor(y);
        Ok(())
    }

    /// Prepare the preview content of the current item if preview is on.
    pub fn prepare_previews(&mut self) {
        if self.layout.side != Side::Preview {
            return;
        }
        let index = self.layout.nums.index;
        if let Some(item) = self.list.get_mut(index) {
            if item.preview_type.is_none() {
                set_preview_type(item);
            }
        }
    }

    pub fn delete_cursor(&self) {
        delete_cursor();
    }

    // ---------- navigation ----------

    /// Change directory and reset position to the top.
    pub fn chdir_to_top(&mut self, p: &Path) -> Result<(), FxError> {
        std::env::set_current_dir(p)?;
        self.current_dir = p.to_path_buf();
        self.keyword = None;
        self.layout.nums.reset();
        self.update_list()?;
        self.layout.preview_scroll = 0;
        Ok(())
    }

    pub fn zoxide_add(&self) {
        let _ = Command::new("zoxide")
            .args(["add", &self.current_dir.display().to_string()])
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status();
    }

    // ---------- file operations ----------

    /// Yank selected items (visual mode) or the current item.
    pub fn yank_targets(&self) -> Vec<ItemBuffer> {
        if self.v_start.is_some() {
            self.list
                .iter()
                .filter(|x| x.selected)
                .map(ItemBuffer::new)
                .collect()
        } else {
            match self.get_item() {
                Ok(item) => vec![ItemBuffer::new(item)],
                Err(_) => vec![],
            }
        }
    }

    /// Move items to the trash directory. Returns the trash paths.
    pub fn remove_and_yank(
        &mut self,
        targets: &[ItemBuffer],
        new_op: bool,
    ) -> Result<Vec<PathBuf>, FxError> {
        let total = targets.len();
        let mut trash_vec = vec![];
        for (i, item) in targets.iter().enumerate() {
            print_process(format!("{}/{}", i + 1, total));
            let trash_name = format!(
                "{}_{}",
                unix_now(),
                item.file_name
            );
            let trash_path = self.trash_dir.join(&trash_name);
            match item.file_type {
                FileType::Directory => {
                    copy_dir_all(&item.file_path, &trash_path)?;
                    remove_dir_all_safe(&item.file_path)?;
                }
                _ => {
                    if item.file_path.symlink_metadata().is_ok() {
                        if item.file_path.symlink_metadata()?.file_type().is_symlink() {
                            // copy the symlink itself
                            if let Ok(target) = fs::read_link(&item.file_path) {
                                let _ = std::os::unix::fs::symlink(&target, &trash_path);
                            }
                        } else {
                            fs::copy(&item.file_path, &trash_path)
                                .map_err(|_| FxError::PutItem(item.file_path.clone()))?;
                        }
                    }
                    fs::remove_file(&item.file_path)
                        .map_err(|_| FxError::RemoveItem(item.file_path.clone()))?;
                }
            }
            trash_vec.push(trash_path);
        }
        if new_op {
            self.operations.branch();
            self.operations.push(OpKind::Delete(DeletedFiles {
                trash: trash_vec.clone(),
                original: targets.iter().map(|x| x.file_path.clone()).collect(),
                dir: self.current_dir.clone(),
            }));
        }
        Ok(trash_vec)
    }

    /// Put items into the current directory. Returns the new paths.
    pub fn put_items(
        &mut self,
        targets: &[ItemBuffer],
        new_op: bool,
    ) -> Result<Vec<PathBuf>, FxError> {
        let total = targets.len();
        let mut put_vec = vec![];
        for (i, item) in targets.iter().enumerate() {
            print_process(format!("{}/{}", i + 1, total));
            let name_set = get_name_set(&self.current_dir);
            match item.file_type {
                FileType::Directory => {
                    let new_name = if name_set.contains(&item.file_name) {
                        rename_dir(&item.file_name, &name_set)
                    } else {
                        item.file_name.clone()
                    };
                    let dest = self.current_dir.join(&new_name);
                    copy_dir_all(&item.file_path, &dest)?;
                    put_vec.push(dest);
                }
                _ => {
                    let new_name = if name_set.contains(&item.file_name) {
                        rename_file(&item.file_name, &name_set)
                    } else {
                        item.file_name.clone()
                    };
                    let dest = self.current_dir.join(&new_name);
                    copy_file_or_link(&item.file_path, &dest)?;
                    put_vec.push(dest);
                }
            }
        }
        if new_op {
            self.operations.branch();
            self.operations.push(OpKind::Put(PutFiles {
                original: targets.iter().map(|x| x.file_path.clone()).collect(),
                put: put_vec.clone(),
                dir: self.current_dir.clone(),
            }));
        }
        Ok(put_vec)
    }

    /// Undo the last operation.
    pub fn undo(&mut self, op: &OpKind) -> Result<(), FxError> {
        match op {
            OpKind::Rename(op) => {
                fs::rename(&op.new_name, &op.original_name)?;
                self.update_list()?;
                self.clear_and_show_headline();
                self.list_up();
                print_info("UNDONE: RENAME", self.layout.y);
            }
            OpKind::Put(op) => {
                for x in &op.put {
                    if x.is_dir() {
                        remove_dir_all_safe(x)?;
                    } else {
                        fs::remove_file(x)?;
                    }
                }
                self.update_list()?;
                self.clear_and_show_headline();
                self.list_up();
                print_info("UNDONE: PUT", self.layout.y);
            }
            OpKind::Delete(op) => {
                let targets: Vec<ItemBuffer> = op
                    .trash
                    .iter()
                    .zip(op.original.iter())
                    .map(|(trash, original)| ItemBuffer {
                        file_type: if trash.is_dir() {
                            FileType::Directory
                        } else {
                            FileType::File
                        },
                        file_name: original
                            .file_name()
                            .map(|n| n.to_string_lossy().into_owned())
                            .unwrap_or_default(),
                        file_path: trash.clone(),
                    })
                    .collect();
                let total = targets.len();
                for (i, item) in targets.iter().enumerate() {
                    print_process(format!("{}/{}", i + 1, total));
                    let dest = op.original[i].clone();
                    if item.file_type == FileType::Directory {
                        copy_dir_all(&item.file_path, &dest)?;
                    } else {
                        copy_file_or_link(&item.file_path, &dest)?;
                    }
                }
                self.update_list()?;
                self.clear_and_show_headline();
                self.list_up();
                print_info("UNDONE: DELETE", self.layout.y);
            }
        }
        relog(op, true);
        Ok(())
    }

    /// Redo the operation.
    pub fn redo(&mut self, op: &OpKind) -> Result<(), FxError> {
        match op {
            OpKind::Rename(op) => {
                fs::rename(&op.original_name, &op.new_name)?;
                self.update_list()?;
                self.clear_and_show_headline();
                self.list_up();
                print_info("REDONE: RENAME", self.layout.y);
            }
            OpKind::Put(op) => {
                let targets: Vec<ItemBuffer> = op
                    .original
                    .iter()
                    .map(|p| ItemBuffer {
                        file_type: if p.is_dir() {
                            FileType::Directory
                        } else {
                            FileType::File
                        },
                        file_name: p
                            .file_name()
                            .map(|n| n.to_string_lossy().into_owned())
                            .unwrap_or_default(),
                        file_path: p.clone(),
                    })
                    .collect();
                let saved_dir = self.current_dir.clone();
                self.current_dir = op.dir.clone();
                let result = self.put_items(&targets, false);
                self.current_dir = saved_dir;
                result?;
                self.update_list()?;
                self.clear_and_show_headline();
                self.list_up();
                print_info("REDONE: PUT", self.layout.y);
            }
            OpKind::Delete(op) => {
                let targets: Vec<ItemBuffer> = op
                    .original
                    .iter()
                    .map(|p| ItemBuffer {
                        file_type: if p.is_dir() {
                            FileType::Directory
                        } else {
                            FileType::File
                        },
                        file_name: p
                            .file_name()
                            .map(|n| n.to_string_lossy().into_owned())
                            .unwrap_or_default(),
                        file_path: p.clone(),
                    })
                    .collect();
                self.remove_and_yank(&targets, false)?;
                self.update_list()?;
                self.clear_and_show_headline();
                self.list_up();
                print_info("REDONE DELETE", self.layout.y);
            }
        }
        relog(op, false);
        Ok(())
    }

    // ---------- opening files ----------

    /// Open the file with the default editor or the configured command.
    pub fn open_file(&self, item: &ItemInfo) -> Result<std::process::ExitStatus, FxError> {
        let path = &item.file_path;
        let ext = item.file_ext.as_deref();
        let mut cmd = match self.command_for_ext(ext) {
            Some((program, args)) => {
                let mut c = Command::new(program);
                c.args(args);
                c
            }
            None => {
                let program = self.default_command()?;
                Command::new(program)
            }
        };
        cmd.arg(path)
            .status()
            .map_err(|_| FxError::DefaultEditor)
    }

    /// Open the file in a new window (detached) with the configured command.
    pub fn open_file_in_new_window(&self, item: &ItemInfo) -> Result<(), FxError> {
        let ext = item.file_ext.as_deref();
        match self.command_for_ext(ext) {
            Some((program, args)) => {
                Command::new(program)
                    .args(args)
                    .arg(&item.file_path)
                    .stdin(Stdio::null())
                    .stdout(Stdio::null())
                    .stderr(Stdio::null())
                    .spawn()
                    .map_err(|e| FxError::OpenNewWindow(e.to_string()))?;
                Ok(())
            }
            None => Err(FxError::NoExecConfig),
        }
    }

    fn command_for_ext(&self, ext: Option<&str>) -> Option<(String, Vec<String>)> {
        let ext = ext?;
        let commands = self.commands.as_ref()?;
        let cmd = commands.get(ext)?;
        let mut parts = cmd.split_whitespace();
        let program = parts.next()?.to_owned();
        let args: Vec<String> = parts.map(|s| s.to_owned()).collect();
        Some((program, args))
    }

    fn default_command(&self) -> Result<String, FxError> {
        match &self.default {
            Some(d) => Ok(d.clone()),
            None => std::env::var("EDITOR").map_err(|_| FxError::DefaultEditor),
        }
    }

    // ---------- selection ----------

    pub fn reset_selection(&mut self) {
        for item in self.list.iter_mut() {
            item.selected = false;
        }
    }

    pub fn select_from_to(&mut self, from: usize, to: usize) {
        let (a, b) = if from <= to { (from, to) } else { (to, from) };
        for (i, item) in self.list.iter_mut().enumerate() {
            item.selected = i >= a && i <= b;
        }
    }

    // ---------- session ----------

    pub fn write_session(&self, session_path: &Path) -> Result<(), FxError> {
        write_session(
            session_path,
            self.layout.sort_by,
            self.layout.show_hidden,
            self.layout.side == Side::Preview,
            self.layout.split,
        )
    }

    pub fn write_lwd(&self) -> Result<(), FxError> {
        match &self.lwd_file {
            Some(p) => {
                fs::write(p, self.current_dir.display().to_string())?;
                Ok(())
            }
            None => Err(FxError::Shell),
        }
    }
}

/// Build an item from a directory entry.
pub fn make_item(entry: &fs::DirEntry) -> ItemInfo {
    let path = entry.path();
    let metadata = fs::symlink_metadata(&path);
    let name = entry.file_name().to_string_lossy().into_owned();
    let is_hidden = name.starts_with('.');
    let (file_type, symlink_dir_path, symlink_target) = match &metadata {
        Ok(m) => {
            let ft = m.file_type();
            if ft.is_symlink() {
                let target = fs::canonicalize(&path).ok();
                let dir_path = match &target {
                    Some(t) if t.is_dir() => Some(t.clone()),
                    _ => None,
                };
                (FileType::Symlink, dir_path, target)
            } else if ft.is_dir() {
                (FileType::Directory, None, None)
            } else {
                (FileType::File, None, None)
            }
        }
        Err(_) => (FileType::File, None, None),
    };
    let file_size = metadata.as_ref().map(|m| m.len()).unwrap_or(0);
    let modified = metadata.as_ref().ok().and_then(|m| m.modified().ok());
    let permissions = metadata.as_ref().ok().map(|m| m.permissions().mode());
    let file_ext = match file_type {
        FileType::Directory => None,
        _ => path
            .extension()
            .map(|e: &OsStr| e.to_string_lossy().into_owned()),
    };
    let is_dir = path.is_dir();
    ItemInfo {
        file_type,
        file_name: name,
        file_path: path,
        symlink_dir_path,
        symlink_target,
        file_size,
        file_ext,
        modified,
        is_hidden,
        selected: false,
        matches: false,
        preview_type: None,
        content: None,
        permissions,
        is_dir,
    }
}

/// Determine the preview type (and read content for text files).
pub fn set_preview_type(item: &mut ItemInfo) {
    if item.file_type == FileType::Directory || item.symlink_dir_path.is_some() {
        item.preview_type = Some(PreviewType::Directory);
        return;
    }
    if item.file_size > MAX_SIZE_TO_PREVIEW {
        item.preview_type = Some(PreviewType::TooBigSize);
        return;
    }
    let path = item.file_path.clone();
    if is_image(&path) {
        item.preview_type = Some(PreviewType::Image);
        return;
    }
    match fs::read(&path) {
        Ok(bytes) => {
            if is_binary(&bytes) {
                item.preview_type = Some(PreviewType::Binary);
            } else {
                item.preview_type = Some(PreviewType::Text);
                item.content = String::from_utf8(bytes).ok();
            }
        }
        Err(_) => {
            item.preview_type = None;
        }
    }
}

/// Check the first 12 bytes for image signatures.
pub fn is_image(path: &Path) -> bool {
    let mut file = match fs::File::open(path) {
        Ok(f) => f,
        Err(_) => return false,
    };
    let mut buf = [0u8; 12];
    if file.read_exact(&mut buf).is_err() {
        return false;
    }
    let b = &buf;
    if b.starts_with(b"\x89PNG\r\n\x1a\n") {
        return true;
    }
    if b.starts_with(b"\xff\xd8\xff\xdb")
        || b.starts_with(b"\xff\xd8\xff\xe0")
        || b.starts_with(b"\xff\xd8\xff\xee")
    {
        return true;
    }
    if b.starts_with(b"\xff\xd8\xff\xe1") && &b[6..12] == b"Exif\x00\x00" {
        return true;
    }
    if b.starts_with(b"GIF87a") || b.starts_with(b"GIF89a") {
        return true;
    }
    if b.starts_with(b"RIFF") {
        return true;
    }
    if b.starts_with(b"BM") {
        return true;
    }
    if b.starts_with(b"II*\x00")
        || b.starts_with(b"MM\x00*")
        || b.starts_with(b"II+\x00")
        || b.starts_with(b"MM\x00+")
    {
        return true;
    }
    if b.starts_with(b"\x00\x00\x01\x00") {
        return true;
    }
    for p in [b"P1\n", b"P2\n", b"P3\n", b"P4\n", b"P5\n", b"P6\n"] {
        if b.starts_with(p) {
            return true;
        }
    }
    if b.starts_with(b"v/1\x01") {
        return true;
    }
    if b.starts_with(b"#?RADIANCE\n") {
        return true;
    }
    false
}

/// Binary detection: known binary signatures or NUL bytes in the first 1024 bytes
/// (unless the file starts with a byte order mark).
pub fn is_binary(bytes: &[u8]) -> bool {
    if bytes.starts_with(b"\x89PNG") || bytes.starts_with(b"%PDF") {
        return true;
    }
    const BOMS: [&[u8]; 5] = [
        b"\xef\xbb\xbf",
        b"\xff\xfe\x00\x00",
        b"\x00\x00\xfe\xff",
        b"\xff\xfe",
        b"\xfe\xff",
    ];
    for bom in BOMS {
        if bytes.starts_with(bom) {
            return false;
        }
    }
    let scan = std::cmp::min(bytes.len(), 1024);
    bytes[..scan].contains(&0)
}

/// Copy a directory recursively.
pub fn copy_dir_all(from: &Path, to: &Path) -> Result<(), FxError> {
    fs::create_dir_all(to)?;
    for entry in fs::read_dir(from)? {
        let entry = entry?;
        let ft = entry.file_type()?;
        let dest = to.join(entry.file_name());
        if ft.is_dir() {
            copy_dir_all(&entry.path(), &dest)?;
        } else if ft.is_symlink() {
            let target = fs::read_link(entry.path())?;
            std::os::unix::fs::symlink(target, &dest)?;
        } else {
            fs::copy(entry.path(), &dest)?;
        }
    }
    Ok(())
}

/// Copy a file, or recreate a symlink.
pub fn copy_file_or_link(from: &Path, to: &Path) -> Result<(), FxError> {
    let meta = fs::symlink_metadata(from).map_err(|_| FxError::PutItem(from.to_path_buf()))?;
    if meta.file_type().is_symlink() {
        let target = fs::read_link(from)?;
        std::os::unix::fs::symlink(target, to)?;
    } else {
        fs::copy(from, to).map_err(|_| FxError::PutItem(from.to_path_buf()))?;
    }
    Ok(())
}

pub fn remove_dir_all_safe(p: &Path) -> Result<(), FxError> {
    fs::remove_dir_all(p).map_err(|_| FxError::RemoveItem(p.to_path_buf()))?;
    Ok(())
}
