                    if reg.is_ascii_lowercase() {
                        state.registers.set_named(reg, targets.clone());
                    } else {
                        state
                            .registers
                            .append_named(reg.to_ascii_lowercase(), targets.clone());
                    }
                    state.registers.numbered.push_front(targets.clone());
                    state.registers.numbered.truncate(9);
                    log::info!(
                        "DELETE: {:?}",
                        targets.iter().map(|x| x.file_path.clone()).collect::<Vec<_>>()
                    );
                    state.v_start = None;
