    LeaveAlternateScreen,
};
use std::fs;
use std::io::{stdout, Write};
use std::path::{Path, PathBuf};
use std::time::Instant;
use unicode_width::UnicodeWidthChar;

use crate::config::*;
use crate::errors::FxError;
use crate::functions::*;
use crate::help::HELP;
use crate::layout::*;
use crate::op::*;
use crate::session::*;
use crate::state::*;
use crate::term::*;

pub const TRASH: &str = "Trash";
pub const LOG_DIR: &str = "log";

/// Where to go after an input mode ends.
enum InputResult {
    Done(String),
    Cancel,
}

pub fn run(arg: PathBuf, log: bool) -> Result<(), FxError> {
    // Prepare directories.
    let config_dir_path = config_base_dir()
        .ok_or_else(|| FxError::Dirs("Cannot read the config directory.".to_owned()))?;
    let data_dir_path = data_base_dir()
        .ok_or_else(|| FxError::Dirs("Cannot read the data directory.".to_owned()))?;
    let config_dir = config_dir_path.join(FX_CONFIG_DIR);
    let data_dir = data_dir_path.join(FX_CONFIG_DIR);
    let trash_dir = data_dir.join(TRASH);
    let runtime_dir = {
        if let Some(p) = std::env::var_os("XDG_RUNTIME_DIR").filter(|p| !p.is_empty()) {
            PathBuf::from(p).join(FX_CONFIG_DIR)
        } else if let Some(p) = std::env::var_os("TMPDIR").filter(|p| !p.is_empty()) {
            PathBuf::from(p).join(FX_CONFIG_DIR)
        } else {
            PathBuf::from("/tmp").join(FX_CONFIG_DIR)
        }
    };
    let lwd_file = std::env::var("SHELL_PID")
        .ok()
        .map(|pid| runtime_dir.join(pid));

    fs::create_dir_all(&config_dir)?;
    fs::create_dir_all(&trash_dir)?;
    fs::create_dir_all(&runtime_dir)?;

    if log {
        let log_dir = data_dir.join(LOG_DIR);
        fs::create_dir_all(&log_dir)?;
        let now = chrono::Local::now();
        let log_name = format!("{}.log", now.format("%Y-%m-%d-%H-%M-%S"));
        crate::logger::init(&log_dir.join(log_name))?;
        log::info!("===START===");
    }

    let config = read_config_or_default();
    let session_path = data_dir.join(SESSION_FILE);
    let session = read_session(&session_path);

    let (column, row) = terminal_size().ok_or(FxError::TerminalSizeDetection)?;
    if column < 4 || row < 4 {
        return Err(FxError::TooSmallWindowSize);
    }

    let mut state = State::new(
        &config,
        &session,
        column,
        row,
        arg.clone(),
        trash_dir,
        lwd_file,
    );
    let _ = std::env::set_current_dir(&arg);
    state.update_list()?;

    let mut screen = stdout();
    execute!(screen, SavePosition, Hide, EnterAlternateScreen)?;
    enable_raw_mode()?;

    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        main_loop(&mut state, &session_path)
    }));

    match result {
        Ok(r) => r,
        Err(e) => {
            let _ = disable_raw_mode();
            let _ = execute!(stdout(), Show, Clear(ClearType::All), MoveTo(0, 0));
            if let Some(s) = e.downcast_ref::<String>() {
                println!("Panic: {}", s);
            } else {
                println!("{:?}", e);
            }
            Err(FxError::Panic)
        }
    }
}

fn main_loop(state: &mut State, session_path: &Path) -> Result<(), FxError> {
    let mut screen = stdout();
    state.redraw(BEGINNING_ROW);

    'main: loop {
        if state.list.is_empty() {
            state.layout.nums.reset();
            state.redraw(BEGINNING_ROW);
        }
        let len = state.list.len();
        let y = state.layout.y;
        let ev = event::read()?;
        match ev {
            Event::Key(KeyEvent {
                code, modifiers, ..
            }) => {
                let alt = modifiers.contains(KeyModifiers::ALT);
                let ctrl = modifiers.contains(KeyModifiers::CONTROL);
                match (code, alt, ctrl) {
                    // ----- move down -----
                    (KeyCode::Char('j'), false, false) | (KeyCode::Down, false, false) => {
                        if len == 0 || state.layout.nums.index == len - 1 {
                            continue;
                        }
                        if y >= state.layout.terminal_row.saturating_sub(5) {
                            state.layout.nums.go_down();
                            state.layout.nums.inc_skip();
                            state.redraw(y);
                        } else {
                            state.layout.nums.go_down();
                            state.prepare_previews();
                            state.move_cursor(y + 1);
                        }
                    }
                    // ----- move up -----
                    (KeyCode::Char('k'), false, false) | (KeyCode::Up, false, false) => {
                        if len == 0 || state.layout.nums.index == 0 {
                            continue;
                        }
                        if y <= BEGINNING_ROW + SCROLL_POINT && state.layout.nums.skip != 0 {
                            state.layout.nums.go_up();
                            state.layout.nums.dec_skip();
                            state.redraw(y);
                        } else {
                            state.layout.nums.go_up();
                            state.prepare_previews();
                            state.move_cursor(y - 1);
                        }
                    }
                    // ----- preview scroll -----
                    (KeyCode::Char('j'), true, false) | (KeyCode::Down, true, false) => {
                        if state.layout.side == Side::Preview {
                            state.layout.preview_scroll += 1;
                            state.scroll_preview(y);
                        }
                    }
                    (KeyCode::Char('k'), true, false) | (KeyCode::Up, true, false) => {
                        if state.layout.side == Side::Preview {
                            if state.layout.preview_scroll > 0 {
                                state.layout.preview_scroll -= 1;
                            }
                            state.scroll_preview(y);
                        }
                    }
                    // ----- half page -----
                    (KeyCode::Char('d'), false, true) => {
                        if len == 0 {
                            continue;
                        }
                        state.half_page_down();
                    }
                    (KeyCode::Char('u'), false, true) => {
                        if len == 0 {
                            continue;
                        }
                        state.half_page_up();
                    }
                    // ----- go to top -----
                    (KeyCode::Char('g'), false, false) => {
                        if len == 0 {
                            continue;
                        }
                        move_to(1, INFO_ROW);
                        clear_current_line();
                        print("g");
                        show_cursor();
                        if let Event::Key(KeyEvent { code, .. }) = event::read()? {
                            if code == KeyCode::Char('g') {
                                hide_cursor();
                                state.layout.nums.go_top();
                                state.redraw(BEGINNING_ROW);
                            } else {
                                hide_cursor();
                                clear_current_line();
                                state.move_cursor(y);
                            }
                        }
                    }
                    // ----- go to bottom -----
                    (KeyCode::Char('G'), false, false) => {
                        if len == 0 {
                            continue;
                        }
                        state.go_bottom();
                    }
                    // ----- open / enter -----
                    (KeyCode::Char('l'), false, false)
                    | (KeyCode::Enter, false, false)
                    | (KeyCode::Right, false, false) => {
                        if len == 0 {
                            continue;
                        }
                        let item = state.get_item()?.clone();
                        match item.file_type {
                            FileType::File => {
                                execute!(screen, EnterAlternateScreen)?;
                                let result = state.open_file(&item);
                                execute!(screen, EnterAlternateScreen, Hide)?;
                                state.reload(y)?;
                                if let Err(e) = result {
                                    print_warning(e, y);
                                }
                            }
                            FileType::Symlink => {
                                if let Some(p) = &item.symlink_dir_path {
                                    let p = p.clone();
                                    state.enter_dir(&p, &item.file_path)?;
                                } else {
                                    execute!(screen, EnterAlternateScreen)?;
                                    let result = state.open_file(&item);
                                    execute!(screen, EnterAlternateScreen, Hide)?;
                                    state.reload(y)?;
                                    if let Err(e) = result {
                                        print_warning(e, y);
                                    }
                                }
                            }
                            FileType::Directory => {
                                let p = item.file_path.clone();
                                state.enter_dir(&p, &p)?;
                            }
                        }
                    }
                    // ----- open in new window -----
                    (KeyCode::Char('o'), false, false) => {
                        if len == 0 {
                            continue;
                        }
                        let item = state.get_item()?.clone();
                        match item.file_type {
                            FileType::Directory => continue,
                            FileType::Symlink if item.symlink_dir_path.is_some() => continue,
                            _ => {
                                let result = state.open_file_in_new_window(&item);
                                hide_cursor();
                                state.redraw(y);
                                if let Err(e) = result {
                                    print_warning(e, y);
                                }
                            }
                        }
                    }
                    // ----- parent -----
                    (KeyCode::Char('h'), false, false) | (KeyCode::Left, false, false) => {
                        state.go_parent()?;
                    }
                    // ----- toggle preview -----
                    (KeyCode::Char('v'), false, false) => {
                        state.toggle_preview(y);
                    }
                    // ----- toggle split -----
                    (KeyCode::Char('s'), false, false) => {
                        if state.layout.side == Side::Preview {
                            state.layout.split = match state.layout.split {
                                Split::Vertical => Split::Horizontal,
                                Split::Horizontal => Split::Vertical,
                            };
                            state.refresh_layout();
                            state.redraw(state.layout.y);
                        }
