                    // ----- toggle hidden -----
                    (KeyCode::Backspace, false, false) => {
                        state.layout.show_hidden = !state.layout.show_hidden;
                        state.layout.nums.reset();
                        state.reload(BEGINNING_ROW)?;
                    }
                    // ----- toggle sort -----
                    (KeyCode::Char('t'), false, false) => {
                        state.layout.sort_by = match state.layout.sort_by {
