                    }
                    // ----- new file / dir -----
                    (KeyCode::Char('i'), false, false) => {
                        delete_cursor();
                        move_to(1, INFO_ROW);
                        clear_current_line();
                        print("New file: ");
                        show_cursor();
                        match read_input("New file: ", "", state)? {
