                            if code == KeyCode::Char('y') {
                                let targets = state.yank_targets();
                                state.registers.yank_item(targets);
                                state.move_cursor(y);
                                print_info("1 item yanked.", y);
                            } else {
                                state.move_cursor(y);
                            }
                        }
                    }
                    // ----- delete -----
                    (KeyCode::Char('d'), false, false) => {
                        if len == 0 {
                            continue;
                        }
                        move_to(1, INFO_ROW);
                        clear_current_line();
                        print("d");
                        show_cursor();
                        if let Event::Key(KeyEvent { code, .. }) = event::read()? {
                            if code == KeyCode::Char('d') {
                                hide_cursor();
                                let start = Instant::now();
                                print_info("DELETE: Processing...", y);
                                let targets = state.yank_targets();
                                let trash = state.remove_and_yank(&targets, true)?;
                                state.registers.delete_item(targets.clone());
                                log::info!(
                                    "DELETE: {:?}",
                                    targets.iter().map(|x| x.file_path.clone()).collect::<Vec<_>>()
                                );
                                let _ = trash;
                                state.update_list()?;
                                let new_y = state.adjust_after_delete(y);
                                state.clear_and_show_headline();
                                state.list_up();
                                let msg = format!(
                                    "1 item deleted. {}",
                                    duration_to_string(start.elapsed())
                                );
                                print_info(msg, new_y);
                                state.move_cursor(new_y);
                            } else {
                                move_to(1, INFO_ROW);
                                clear_current_line();
                                hide_cursor();
                                state.move_cursor(y);
                            }
                        }
                    }
                    // ----- put -----
                    (KeyCode::Char('p'), false, false) => {
                        let targets = state.registers.zero.clone();
                        if targets.is_empty() {
                            continue;
                        }
                        state.put_from_register(&targets, y)?;
                    }
                    // ----- registers -----
                    (KeyCode::Char('"'), false, false) => {
                        register_mode(state, y)?;
                    }
                    // ----- visual mode -----
                    (KeyCode::Char('V'), false, false) => {
                        if len == 0 {
                            continue;
                        }
                        visual_mode(state, &mut screen)?;
                    }
                    // ----- undo / redo -----
                    (KeyCode::Char('u'), false, false) => {
                        let pos = state.operations.pos;
                        let op_len = state.operations.op_list.len();
                        if op_len == 0 || pos >= op_len {
                            print_info("No operations left.", y);
                            continue;
                        }
                        let op = state.operations.op_list[op_len - pos - 1].clone();
                        state.undo(&op)?;
                        state.operations.pos += 1;
                        let new_y = state.fix_cursor_after_reload(y);
                        state.move_cursor(new_y);
                    }
                    (KeyCode::Char('r'), false, true) => {
                        let pos = state.operations.pos;
                        let op_len = state.operations.op_list.len();
                        if pos == 0 || op_len == 0 {
                            print_info("No operations left.", y);
                            continue;
                        }
                        let op = state.operations.op_list[op_len - pos].clone();
                        state.redo(&op)?;
                        state.operations.pos -= 1;
                        let new_y = state.fix_cursor_after_reload(y);
                        state.move_cursor(new_y);
                    }
                    // ----- unpack -----
                    (KeyCode::Char('e'), false, false) => {
                        let start = Instant::now();
                        print_info("Unpacking...", y);
                        let result = match state.get_item() {
                            Ok(item) => {
                                let item = item.clone();
                                crate::unpack::unpack(&item.file_path, &state.current_dir)
                            }
                            Err(e) => Err(e),
                        };
                        match result {
                            Ok(_) => {
                                state.reload(y)?;
                                print_info(
                                    format!("Unpacked. {}", duration_to_string(start.elapsed())),
                                    y,
                                );
                            }
                            Err(e) => {
                                state.reload(y)?;
                                print_warning(e, y);
                            }
                        }
                    }
                    // ----- zoxide -----
                    (KeyCode::Char('z'), false, false) => {
                        if !check_zoxide() {
                            print_warning("zoxide not found.", y);
                            continue;
                        }
                        delete_cursor();
                        move_to(1, INFO_ROW);
                        clear_current_line();
                        print("z");
                        show_cursor();
                        match read_simple_input("z", state)? {
                            InputResult::Done(input) => {
                                hide_cursor();
                                let trimmed = input.trim();
                                if trimmed == "z" {
                                    // go home
                                    match home_dir() {
                                        Some(home) => {
                                            state.chdir_to_top(&home)?;
                                            state.jumplist.add(&home);
                                            state.zoxide_add();
                                            state.redraw(BEGINNING_ROW);
                                        }
                                        None => {
                                            print_warning("Cannot read home dir.", y);
                                        }
                                    }
                                } else {
                                    let keyword = input[1..].trim().to_owned();
                                    let output = std::process::Command::new("zoxide")
                                        .args(["query", &keyword])
                                        .output();
                                    hide_cursor();
                                    match output {
                                        Ok(out) if out.status.success() => {
                                            let p = String::from_utf8_lossy(&out.stdout)
                                                .trim()
                                                .to_owned();
                                            let p = PathBuf::from(p);
                                            match state.chdir_to_top(&p) {
                                                Ok(_) => {
                                                    state.jumplist.add(&p);
                                                    state.zoxide_add();
                                                    state.redraw(BEGINNING_ROW);
                                                }
                                                Err(e) => {
                                                    print_warning(e, y);
                                                }
                                            }
                                        }
                                        _ => {
                                            print_warning(
                                                "Keyword does not match the database.",
                                                y,
                                            );
                                        }
                                    }
                                }
                            }
                            InputResult::Cancel => {
                                cancel_input(state, y);
                            }
                        }
                    }
                    // ----- jumplist -----
                    (KeyCode::Char('o'), false, true) => {
                        if let Some(p) = state.jumplist.backward() {
                            if state.chdir_to_top(&p).is_ok() {
                                state.zoxide_add();
                                state.redraw(BEGINNING_ROW);
                            }
                        }
                    }
                    (KeyCode::Char('i'), false, true) | (KeyCode::Tab, false, false) => {
                        if let Some(p) = state.jumplist.forward() {
                            if state.chdir_to_top(&p).is_ok() {
                                state.zoxide_add();
                                state.redraw(BEGINNING_ROW);
                            }
                        }
                    }
                    // ----- ZZ / ZQ -----
                    (KeyCode::Char('Z'), false, false) => {
                        delete_cursor();
                        move_to(1, INFO_ROW);
                        clear_current_line();
                        print("Z");
                        show_cursor();
                        if let Event::Key(KeyEvent { code, .. }) = event::read()? {
                            match code {
                                KeyCode::Char('Z') => {
                                    if state.match_vim_exit_behavior {
                                        if let Err(e) = state.write_lwd() {
                                            print_warning(e, y);
                                            continue;
                                        }
                                    }
                                    break 'main;
                                }
                                KeyCode::Char('Q') => {
                                    if !state.match_vim_exit_behavior {
                                        if let Err(e) = state.write_lwd() {
                                            print_warning(e, y);
                                            continue;
                                        }
                                    }
                                    break 'main;
                                }
                                _ => {
                                    move_to(1, INFO_ROW);
                                    clear_current_line();
                                    hide_cursor();
                                    state.move_cursor(y);
                                }
                            }
                        }
                    }
                    // ----- escape -----
                    (KeyCode::Esc, false, false) => {
                        state.redraw(y);
                    }
                    _ => {}
                }
            }
            Event::Resize(column, row) => {
                if column < 4 {
                    panic!("Error: Too small terminal size (less than 4 columns). Please restart.");
                }
                if row < 4 {
                    panic!("Error: Too small terminal size (less than 4 rows). Please restart.");
                }
                state.refresh(column, row);
                let mut new_y = state.layout.y;
                if new_y > state.layout.terminal_row - 2 {
                    new_y = state.layout.terminal_row - 2;
                    let idx = state.layout.nums.skip as usize + (new_y - BEGINNING_ROW) as usize;
                    state.layout.nums.index = idx;
                }
                state.redraw(new_y);
            }
            _ => {}
        }
    }

    // Exit.
    let _ = state.write_session(session_path);
    execute!(screen, LeaveAlternateScreen, RestorePosition, Show)?;
    disable_raw_mode()?;
    log::info!("===FINISH===");
    Ok(())
}

/// Esc from an input mode: clear the info row, hide the cursor, redraw the footer.
fn cancel_input(state: &mut State, y: u16) {
    move_to(1, INFO_ROW);
    clear_current_line();
    hide_cursor();
    state.move_cursor(y);
}

/// Width of the string in terminal cells.
fn str_width(s: &str) -> u16 {
    s.chars().map(|c| c.width().unwrap_or(0) as u16).sum()
}

/// Generic text input on the info row. `prompt` is already printed with `initial`.
/// Uses the cursor position report to know where the text starts.
fn read_input(prompt: &str, initial: &str, _state: &mut State) -> Result<InputResult, FxError> {
    let mut chars: Vec<char> = initial.chars().collect();
    let (start_col, _) = match cursor_pos() {
        Ok((x, y)) => {
            let w = str_width(initial);
            (x.saturating_sub(w), y)
        }
        Err(_) => ((prompt.chars().count() + 1) as u16, INFO_ROW),
    };
    let mut pos = chars.len();
    loop {
        if let Event::Key(KeyEvent {
            code, modifiers, ..
        }) = event::read()?
        {
            match code {
                KeyCode::Esc => return Ok(InputResult::Cancel),
                KeyCode::Enter => {
                    return Ok(InputResult::Done(chars.iter().collect()));
                }
                KeyCode::Left => {
                    if pos > 0 {
                        pos -= 1;
                        let w = chars[pos].width().unwrap_or(0) as u16;
                        if w > 0 {
                            move_left(w);
                        }
                    }
                }
                KeyCode::Right => {
                    if pos < chars.len() {
                        let w = chars[pos].width().unwrap_or(0) as u16;
                        pos += 1;
                        if w > 0 {
                            let _ = execute!(stdout(), MoveRight(w));
                        }
                    }
                }
                KeyCode::Backspace => {
                    if pos > 0 {
                        chars.remove(pos - 1);
                        pos -= 1;
                        redraw_input(prompt, &chars, pos, start_col);
                    }
                }
                KeyCode::Char('h') if modifiers.contains(KeyModifiers::CONTROL) => {
                    if pos > 0 {
                        chars.remove(pos - 1);
                        pos -= 1;
                        redraw_input(prompt, &chars, pos, start_col);
                    }
                }
                KeyCode::Char(c) => {
                    if modifiers.contains(KeyModifiers::CONTROL) {
                        continue;
                    }
                    chars.insert(pos, c);
                    pos += 1;
                    redraw_input(prompt, &chars, pos, start_col);
                }
                _ => {}
            }
        }
    }
}

fn redraw_input(prompt: &str, chars: &[char], pos: usize, start_col: u16) {
    let s: String = chars.iter().collect();
    move_to(1, INFO_ROW);
    clear_current_line();
    print(&format!("{}{}", prompt, s));
    let before: String = chars[..pos].iter().collect();
    move_to(start_col + str_width(&before), INFO_ROW);
}

/// Input mode for `z`: text appended after the initial char; redrawn with Clear then MoveTo.
fn read_simple_input(initial: &str, _state: &mut State) -> Result<InputResult, FxError> {
    let mut chars: Vec<char> = initial.chars().collect();
    let mut pos = chars.len();
    loop {
        if let Event::Key(KeyEvent {
            code, modifiers, ..
        }) = event::read()?
        {
            match code {
                KeyCode::Esc => return Ok(InputResult::Cancel),
                KeyCode::Enter => {
                    return Ok(InputResult::Done(chars.iter().collect()));
                }
                KeyCode::Left => {
                    if pos > 1 {
                        pos -= 1;
                        let w = chars[pos].width().unwrap_or(0) as u16;
                        if w > 0 {
                            move_left(w);
                        }
                    }
                }
                KeyCode::Right => {
                    if pos < chars.len() {
                        let w = chars[pos].width().unwrap_or(0) as u16;
                        pos += 1;
                        if w > 0 {
                            let _ = execute!(stdout(), MoveRight(w));
                        }
                    }
                }
                KeyCode::Backspace => {
                    if pos > 1 {
                        chars.remove(pos - 1);
                        pos -= 1;
                        redraw_simple_input(&chars, pos);
                    }
                }
                KeyCode::Char('h') if modifiers.contains(KeyModifiers::CONTROL) => {
                    if pos > 1 {
                        chars.remove(pos - 1);
                        pos -= 1;
                        redraw_simple_input(&chars, pos);
                    }
                }
                KeyCode::Char(c) => {
                    if modifiers.contains(KeyModifiers::CONTROL) {
                        continue;
                    }
                    chars.insert(pos, c);
                    pos += 1;
                    redraw_simple_input(&chars, pos);
                }
                _ => {}
            }
        }
    }
}

fn redraw_simple_input(chars: &[char], pos: usize) {
    let s: String = chars.iter().collect();
    clear_current_line();
    move_to(1, INFO_ROW);
    print(&s);
    let before: String = chars[..pos].iter().collect();
    move_to(1 + str_width(&before), INFO_ROW);
}

/// Command line input (after ':').
fn read_command(state: &mut State) -> Result<InputResult, FxError> {
    let mut chars: Vec<char> = vec![];
    let mut pos = 0usize;
    loop {
        if let Event::Key(KeyEvent {
            code, modifiers, ..
        }) = event::read()?
        {
            match code {
                KeyCode::Esc => return Ok(InputResult::Cancel),
                KeyCode::Enter => {
                    return Ok(InputResult::Done(chars.iter().collect()));
                }
                KeyCode::Left => {
                    if pos > 0 {
                        pos -= 1;
                        let w = chars[pos].width().unwrap_or(0) as u16;
                        if w > 0 {
                            move_left(w);
                        }
                    }
                }
                KeyCode::Right => {
                    if pos < chars.len() {
                        let w = chars[pos].width().unwrap_or(0) as u16;
                        pos += 1;
                        if w > 0 {
                            let _ = execute!(stdout(), MoveRight(w));
                        }
                    }
                }
                KeyCode::Backspace => {
                    if pos > 0 {
                        chars.remove(pos - 1);
                        pos -= 1;
                        redraw_input(":", &chars, pos, 2);
                    }
                }
                KeyCode::Char('h') if modifiers.contains(KeyModifiers::CONTROL) => {
                    if pos > 0 {
                        chars.remove(pos - 1);
                        pos -= 1;
                        redraw_input(":", &chars, pos, 2);
                    }
                }
                KeyCode::Char('r') if modifiers.contains(KeyModifiers::CONTROL) => {
                    // paste from register
                    if let Event::Key(KeyEvent { code, .. }) = event::read()? {
                        if let KeyCode::Char(reg) = code {
                            if let Some(items) = state.registers.get(reg) {
                                let names: Vec<String> =
                                    items.iter().map(|x| x.file_name.clone()).collect();
                                let joined = names.join(" ");
                                for c in joined.chars() {
                                    chars.insert(pos, c);
                                    pos += 1;
                                }
                                redraw_input(":", &chars, pos, 2);
                            }
                        }
                    }
                }
                KeyCode::Char(c) => {
                    if modifiers.contains(KeyModifiers::CONTROL) {
                        continue;
                    }
                    chars.insert(pos, c);
                    pos += 1;
                    redraw_input(":", &chars, pos, 2);
                }
                _ => {}
            }
        }
    }
}

/// Execute a command line. Returns Ok(true) if the app should exit.
fn execute_command(state: &mut State, cmd: &str, _session_path: &Path) -> Result<bool, FxError> {
    let y = state.layout.y;
    let parts: Vec<&str> = cmd.split_whitespace().collect();
    if parts.is_empty() {
        cancel_input(state, y);
        return Ok(false);
    }
    let command = parts[0];
    match (command, parts.len()) {
        ("q", 1) => {
            return Ok(true);
        }
        ("cd", 1) => match home_dir() {
            Some(home) => {
                state.chdir_to_top(&home)?;
                state.jumplist.add(&home);
                state.zoxide_add();
                state.redraw(BEGINNING_ROW);
            }
            None => print_warning("Cannot read home dir.", y),
        },
        ("cd", 2) => {
            let target = PathBuf::from(parts[1]);
            match fs::canonicalize(&target) {
                Ok(p) => match state.chdir_to_top(&p) {
                    Ok(_) => {
                        state.jumplist.add(&p);
                        state.zoxide_add();
                        state.redraw(BEGINNING_ROW);
                    }
                    Err(e) => {
                        print_warning(e, y);
                    }
                },
                Err(_) => {
                    print_warning(FxError::InvalidPath, y);
                }
            }
        }
        ("e", 1) => {
            state.reload(y)?;
        }
        ("reg", 1) => {
            if state.layout.side != Side::Reg {
                state.layout.side = Side::Reg;
                state.refresh_layout();
            }
            state.redraw(y);
            cancel_input(state, y);
        }
        ("h", 1) => {
            show_help(state)?;
        }
        ("config", 1) => match config_file_path() {
            Some(p) => {
                let dir = p
                    .parent()
                    .map(|d| d.to_path_buf())
                    .unwrap_or_else(|| p.clone());
                state.chdir_to_top(&dir)?;
                state.jumplist.add(&dir);
                state.zoxide_add();
                state.redraw(BEGINNING_ROW);
            }
            None => {
                print_warning("Cannot find the config path.", y);
            }
        },
        ("trash", 1) => {
            let trash = state.trash_dir.clone();
            state.chdir_to_top(&trash)?;
            state.jumplist.add(&trash);
            state.zoxide_add();
            state.redraw(BEGINNING_ROW);
        }
        ("empty", 1) => {
            print_warning(
                "Are you sure to empty the trash directory? (if yes: y)",
                y,
            );
            if let Event::Key(KeyEvent { code, .. }) = event::read()? {
                if code == KeyCode::Char('y') {
                    let trash = state.trash_dir.clone();
                    if let Ok(rd) = fs::read_dir(&trash) {
                        for entry in rd.flatten() {
                            let p = entry.path();
                            if p.is_dir() {
                                let _ = fs::remove_dir_all(&p);
                            } else {
                                let _ = fs::remove_file(&p);
                            }
                        }
                    }
                    if state.current_dir == trash {
                        state.layout.nums.reset();
                        state.reload(BEGINNING_ROW)?;
                    }
                    move_to(1, INFO_ROW);
                    clear_current_line();
                    print_info("Trash dir emptied", state.layout.y);
                    let yy = state.layout.y;
                    state.move_cursor(yy);
                } else {
                    move_to(1, INFO_ROW);
                    clear_current_line();
                    state.move_cursor(y);
                }
            }
        }
        _ => {
            // shell command
            let mut screen = stdout();
            execute!(screen, EnterAlternateScreen)?;
            log::info!("SHELL: {:?}", parts);
            let result = std::process::Command::new(command)
                .args(&parts[1..])
                .status();
            execute!(screen, EnterAlternateScreen, Hide)?;
            state.reload(y)?;
            if result.is_err() {
                print_warning("Command execution failed.", y);
            }
        }
    }
    Ok(false)
}

/// Show the help text; scroll with j/k; any other key returns.
fn show_help(state: &mut State) -> Result<(), FxError> {
    let text = format!("{}\nPress <CR> to go back.", HELP);
    let lines: Vec<&str> = text.split('\n').collect();
    let mut skip = 0usize;
    loop {
        print_help(&lines, skip, state.layout.terminal_row_full());
        if let Event::Key(KeyEvent { code, .. }) = event::read()? {
            match code {
                KeyCode::Char('j') | KeyCode::Down => {
                    skip += 1;
                }
                KeyCode::Char('k') | KeyCode::Up => {
                    skip = skip.saturating_sub(1);
                }
                _ => break,
            }
        }
    }
    let y = state.layout.y;
    state.redraw(y);
    Ok(())
}

fn print_help(lines: &[&str], skip: usize, rows: u16) {
    let mut out = stdout();
    let _ = execute!(out, Clear(ClearType::All), MoveTo(0, 0));
    let visible = rows.saturating_sub(1) as usize;
    let mut row = 0u16;
    for (i, line) in lines.iter().enumerate() {
        if i < skip {
            continue;
        }
        if row as usize >= visible {
            break;
        }
        let _ = execute!(out, MoveTo(0, row));
        let _ = out.write_all(line.as_bytes());
        row += 1;
    }
    if lines.len() > skip + visible {
        let _ = execute!(out, MoveTo(0, rows - 1));
        let _ = write!(out, "{}", crossterm::style::Stylize::reverse("..."));
    }
    let _ = out.flush();
}

/// Register mode after `"`.
fn register_mode(state: &mut State, y: u16) -> Result<(), FxError> {
    move_to(1, INFO_ROW);
    clear_current_line();
    print("\"");
    show_cursor();
    let mut typed = String::from("\"");
    // register name
    let reg = loop {
        if let Event::Key(KeyEvent { code, .. }) = event::read()? {
            match code {
                KeyCode::Esc => {
                    cancel_input(state, y);
                    return Ok(());
                }
                KeyCode::Char(c) => {
                    typed.push(c);
                    clear_current_line();
                    move_to(1, INFO_ROW);
                    print(&typed);
                    move_to(1 + str_width(&typed), INFO_ROW);
                    break c;
                }
                _ => {}
            }
        }
    };
    // command
    loop {
        if let Event::Key(KeyEvent { code, .. }) = event::read()? {
            match code {
                KeyCode::Esc => {
                    cancel_input(state, y);
                    return Ok(());
                }
                KeyCode::Char('y') => {
                    typed.push('y');
                    clear_current_line();
                    move_to(1, INFO_ROW);
                    print(&typed);
                    move_to(1 + str_width(&typed), INFO_ROW);
                    if let Event::Key(KeyEvent { code, .. }) = event::read()? {
                        if code == KeyCode::Char('y') {
                            match reg {
                                'a'..='z' => {
                                    move_to(1, INFO_ROW);
                                    clear_current_line();
                                    hide_cursor();
                                    let targets = state.yank_targets();
                                    state.registers.set_named(reg, targets);
                                    state.move_cursor(y);
                                    print_info("1 item yanked.", y);
                                }
                                'A'..='Z' => {
                                    move_to(1, INFO_ROW);
                                    clear_current_line();
                                    hide_cursor();
                                    let targets = state.yank_targets();
                                    state
                                        .registers
                                        .append_named(reg.to_ascii_lowercase(), targets);
                                    state.move_cursor(y);
                                    print_info("1 item yanked.", y);
                                }
                                '0'..='9' | '"' => {
                                    state.move_cursor(y);
                                }
                                _ => {
                                    print_warning("Input not supported.", y);
                                }
                            }
                        } else {
                            clear_current_line();
                            hide_cursor();
                            state.move_cursor(y);
                        }
                    }
                    return Ok(());
                }
                KeyCode::Char('d') => {
                    typed.push('d');
                    clear_current_line();
                    move_to(1, INFO_ROW);
                    print(&typed);
                    move_to(1 + str_width(&typed), INFO_ROW);
                    if let Event::Key(KeyEvent { code, .. }) = event::read()? {
                        if code == KeyCode::Char('d') {
                            match reg {
                                'a'..='z' | 'A'..='Z' => {
                                    hide_cursor();
                                    let start = Instant::now();
                                    print_info("DELETE: Processing...", y);
                                    let targets = state.yank_targets();
                                    state.remove_and_yank(&targets, true)?;
                                    if reg.is_ascii_lowercase() {
                                        state.registers.set_named(reg, targets.clone());
                                    } else {
                                        state.registers.append_named(
                                            reg.to_ascii_lowercase(),
                                            targets.clone(),
                                        );
                                    }
                                    state.registers.numbered.push_front(targets.clone());
                                    state.registers.numbered.truncate(9);
                                    log::info!(
                                        "DELETE: {:?}",
                                        targets
                                            .iter()
                                            .map(|x| x.file_path.clone())
                                            .collect::<Vec<_>>()
                                    );
                                    state.update_list()?;
                                    let new_y = state.adjust_after_delete(y);
                                    state.clear_and_show_headline();
                                    state.list_up();
                                    print_info(
                                        format!(
                                            "1 item deleted. {}",
                                            duration_to_string(start.elapsed())
                                        ),
                                        new_y,
                                    );
                                    state.move_cursor(new_y);
                                    state.move_cursor(new_y);
                                }
                                '0'..='9' | '"' => {
                                    state.move_cursor(y);
                                }
                                _ => {
                                    print_warning("Input not supported.", y);
                                }
                            }
                        } else {
                            clear_current_line();
                            hide_cursor();
                            state.move_cursor(y);
                        }
                    }
                    return Ok(());
                }
                KeyCode::Char('p') => {
                    match state.registers.get(reg) {
                        Some(targets) => {
                            if targets.is_empty() {
                                state.move_cursor(y);
                            } else {
                                state.put_from_register(&targets, y)?;
                            }
                        }
                        None => {
                            print_warning("Register not found.", y);
                            state.move_cursor(y);
                        }
                    }
                    return Ok(());
                }
                KeyCode::Char(c) => {
                    typed.push(c);
                    clear_current_line();
                    move_to(1, INFO_ROW);
                    print(&typed);
                    move_to(1 + str_width(&typed), INFO_ROW);
                    // keep reading
                    let _ = c;
                }
                _ => {}
            }
        }
    }
}

/// Visual (linewise selection) mode.
fn visual_mode(state: &mut State, screen: &mut std::io::Stdout) -> Result<(), FxError> {
    let start = state.layout.nums.index;
    state.v_start = Some(start);
    state.select_from_to(start, start);
    state.redraw(state.layout.y);
    loop {
        let len = state.list.len();
        let y = state.layout.y;
        let ev = event::read()?;
        match ev {
            Event::Key(KeyEvent {
                code, modifiers, ..
            }) => {
                let alt = modifiers.contains(KeyModifiers::ALT);
                let ctrl = modifiers.contains(KeyModifiers::CONTROL);
                match (code, alt, ctrl) {
                    (KeyCode::Char('j'), false, false) | (KeyCode::Down, false, false) => {
                        if len == 0 || state.layout.nums.index >= len - 1 {
                            continue;
                        }
                        if y >= state.layout.terminal_row.saturating_sub(5) {
                            state.layout.nums.go_down();
                            state.layout.nums.inc_skip();
                            let idx = state.layout.nums.index;
                            state.select_from_to(start, idx);
                            state.redraw(y);
                        } else {
                            state.layout.nums.go_down();
                            let idx = state.layout.nums.index;
                            state.select_from_to(start, idx);
                            state.redraw(y + 1);
                        }
                    }
                    (KeyCode::Char('k'), false, false) | (KeyCode::Up, false, false) => {
                        if len == 0 || state.layout.nums.index == 0 {
                            continue;
                        }
                        if y <= BEGINNING_ROW + SCROLL_POINT && state.layout.nums.skip != 0 {
                            state.layout.nums.go_up();
                            state.layout.nums.dec_skip();
                            let idx = state.layout.nums.index;
                            state.select_from_to(start, idx);
                            state.redraw(y);
                        } else {
                            state.layout.nums.go_up();
                            let idx = state.layout.nums.index;
                            state.select_from_to(start, idx);
                            state.redraw(y - 1);
                        }
                    }
                    (KeyCode::Char('g'), false, false) => {
                        move_to(1, INFO_ROW);
                        clear_current_line();
                        print("g");
                        show_cursor();
                        if let Event::Key(KeyEvent { code, .. }) = event::read()? {
                            if code == KeyCode::Char('g') {
                                hide_cursor();
                                state.layout.nums.go_top();
                                state.select_from_to(start, 0);
                                state.redraw(BEGINNING_ROW);
                            } else {
                                hide_cursor();
                                clear_current_line();
                                state.move_cursor(y);
                            }
                        }
                    }
                    (KeyCode::Char('G'), false, false) => {
                        state.select_from_to(start, len - 1);
                        state.go_bottom();
                    }
                    (KeyCode::Char('d'), false, true) => {
                        state.half_page_down();
                        let idx = state.layout.nums.index;
                        state.select_from_to(start, idx);
                        let yy = state.layout.y;
                        state.redraw(yy);
                    }
                    (KeyCode::Char('u'), false, true) => {
                        state.half_page_up();
                        let idx = state.layout.nums.index;
                        state.select_from_to(start, idx);
                        let yy = state.layout.y;
                        state.redraw(yy);
                    }
                    (KeyCode::Char('v'), false, false) => {
                        state.toggle_preview(y);
                    }
                    (KeyCode::Char('s'), false, false) => {
                        if state.layout.side == Side::Preview {
                            state.layout.split = match state.layout.split {
                                Split::Vertical => Split::Horizontal,
                                Split::Horizontal => Split::Vertical,
                            };
                            state.refresh_layout();
                            state.redraw(state.layout.y);
                        }
                    }
                    (KeyCode::Char('y'), false, false) => {
                        let targets = state.yank_targets();
                        let count = targets.len();
                        state.registers.yank_item(targets);
                        state.reset_selection();
                        state.v_start = None;
                        state.list_up();
                        print_info(yank_message(count), y);
                        return Ok(());
                    }
                    (KeyCode::Char('d'), false, false) => {
                        let start_time = Instant::now();
                        print_info("DELETE: Processing...", y);
                        let targets = state.yank_targets();
                        let count = targets.len();
                        state.remove_and_yank(&targets, true)?;
                        state.registers.delete_item(targets.clone());
                        log::info!(
                            "DELETE: {:?}",
                            targets.iter().map(|x| x.file_path.clone()).collect::<Vec<_>>()
                        );
                        state.v_start = None;
                        state.update_list()?;
                        let new_y = state.adjust_after_delete(y);
                        state.clear_and_show_headline();
                        print_info(
                            format!(
                                "{} {}",
                                delete_message(count),
                                duration_to_string(start_time.elapsed())
                            ),
                            new_y,
                        );
                        delete_cursor();
                        state.list_up();
                        state.move_cursor(new_y);
                        return Ok(());
                    }
                    (KeyCode::Char('"'), false, false) => {
                        visual_register_mode(state, y)?;
                        if state.v_start.is_none() {
                            return Ok(());
                        }
                    }
                    (KeyCode::Char('c'), false, false) => {
                        let targets = state.yank_targets();
                        execute!(screen, EnterAlternateScreen)?;
                        let result = rename_in_editor(state, &targets);
                        execute!(screen, EnterAlternateScreen, Hide)?;
                        state.reset_selection();
                        state.v_start = None;
                        match result {
                            Ok(count) => {
                                state.reload(y)?;
                                print_info(format!("{} items renamed.", count), y);
                            }
                            Err(e) => {
                                state.reload(y)?;
                                print_warning(e, y);
                            }
                        }
                        return Ok(());
                    }
                    (KeyCode::Esc, false, false) => {
                        state.reset_selection();
                        state.v_start = None;
                        state.redraw(y);
                        return Ok(());
                    }
                    _ => {}
                }
            }
            Event::Resize(column, row) => {
                if column < 4 {
                    panic!("Error: Too small terminal size (less than 4 columns). Please restart.");
                }
                if row < 4 {
                    panic!("Error: Too small terminal size (less than 4 rows). Please restart.");
                }
                state.refresh(column, row);
                let mut new_y = state.layout.y;
                if new_y > state.layout.terminal_row - 2 {
                    new_y = state.layout.terminal_row - 2;
                    let idx = state.layout.nums.skip as usize + (new_y - BEGINNING_ROW) as usize;
                    state.layout.nums.index = idx;
                }
                state.redraw(new_y);
            }
            _ => {}
        }
    }
}

fn yank_message(count: usize) -> String {
    if count == 1 {
        "1 item yanked.".to_owned()
    } else {
        format!("{} items yanked", count)
    }
}

fn delete_message(count: usize) -> String {
    if count == 1 {
        "1 item deleted.".to_owned()
    } else {
        format!("{} items deleted", count)
    }
}

/// `"` in visual mode: "ay, "ad, "Ay, "Ad.
fn visual_register_mode(state: &mut State, y: u16) -> Result<(), FxError> {
    move_to(1, INFO_ROW);
    clear_current_line();
    print("\"");
    show_cursor();
    let mut typed = String::from("\"");
    let reg = loop {
        if let Event::Key(KeyEvent { code, .. }) = event::read()? {
            match code {
                KeyCode::Esc => {
                    cancel_input(state, y);
                    return Ok(());
                }
                KeyCode::Char(c) => {
                    typed.push(c);
                    clear_current_line();
                    move_to(1, INFO_ROW);
                    print(&typed);
                    move_to(1 + str_width(&typed), INFO_ROW);
                    break c;
                }
                _ => {}
            }
        }
    };
    if let Event::Key(KeyEvent { code, .. }) = event::read()? {
        match code {
            KeyCode::Char('y') => match reg {
                'a'..='z' | 'A'..='Z' => {
                    move_to(1, INFO_ROW);
                    clear_current_line();
                    hide_cursor();
                    let targets = state.yank_targets();
                    let count = targets.len();
                    if reg.is_ascii_lowercase() {
                        state.registers.set_named(reg, targets);
                    } else {
                        state.registers.append_named(reg.to_ascii_lowercase(), targets);
                    }
                    state.reset_selection();
                    state.v_start = None;
                    state.list_up();
                    print_info(yank_message(count), y);
                }
                _ => {
                    print_warning("Input not supported.", y);
                }
            },
            KeyCode::Char('d') => match reg {
                'a'..='z' | 'A'..='Z' => {
                    hide_cursor();
                    let start_time = Instant::now();
                    print_info("DELETE: Processing...", y);
                    let targets = state.yank_targets();
                    let count = targets.len();
                    state.remove_and_yank(&targets, true)?;
                    if reg.is_ascii_lowercase() {
                        state.registers.set_named(reg, targets.clone());
                    } else {
                        state
                            .registers
                            .append_named(reg.to_ascii_lowercase(), targets.clone());
                    }
                    state.registers.numbered.push_front(targets.clone());
                    state.registers.numbered.truncate(9);
                    log::info!(
                        "DELETE: {:?}",
                        targets.iter().map(|x| x.file_path.clone()).collect::<Vec<_>>()
                    );
                    state.v_start = None;
                    state.update_list()?;
                    let new_y = state.adjust_after_delete(y);
                    state.clear_and_show_headline();
                    print_info(
                        format!(
                            "{} {}",
                            delete_message(count),
                            duration_to_string(start_time.elapsed())
                        ),
                        new_y,
                    );
                    delete_cursor();
                    state.list_up();
                    state.move_cursor(new_y);
                }
                _ => {
                    print_warning("Input not supported.", y);
                }
            },
            _ => {
                cancel_input(state, y);
            }
        }
    }
    Ok(())
}

/// Rename selected items by editing their names in the editor.
fn rename_in_editor(state: &State, targets: &[ItemBuffer]) -> Result<usize, FxError> {
    let names: Vec<String> = targets.iter().map(|x| x.file_name.clone()).collect();
    let content = format!("{}\n", names.join("\n"));
    let tmp = crate::functions::create_temp_file(&content)?;
    let editor = match &state.default {
        Some(d) => d.clone(),
        None => std::env::var("EDITOR").map_err(|_| FxError::DefaultEditor)?,
    };
    std::process::Command::new(editor)
        .arg(&tmp)
        .status()
        .map_err(|_| FxError::DefaultEditor)?;
    let edited = fs::read_to_string(&tmp)?;
    let _ = fs::remove_file(&tmp);
    let new_names: Vec<&str> = edited.lines().collect();
    if new_names.len() != targets.len() {
        return Err(FxError::Rename);
    }
    let mut count = 0;
    for (item, new_name) in targets.iter().zip(new_names.iter()) {
        if *new_name == item.file_name {
            continue;
        }
        let to = state.current_dir.join(new_name);
        fs::rename(&item.file_path, &to)?;
        count += 1;
    }
    Ok(count)
}

impl State {
    pub fn refresh_layout(&mut self) {
        let (c, r) = terminal_size().unwrap_or((self.layout.terminal_column, self.layout.terminal_row));
        self.layout.update_size(c, r);
    }

    pub fn toggle_preview(&mut self, y: u16) {
        match self.layout.side {
            Side::Reg => {
                self.layout.side = Side::None;
            }
            Side::Preview => {
                self.layout.side = Side::None;
            }
            Side::None => {
                self.layout.side = Side::Preview;
            }
        }
        self.refresh_layout();
        self.redraw(y);
    }

    pub fn scroll_preview(&mut self, y: u16) {
        if let Some(item) = self.list.get(self.layout.nums.index) {
            let item = item.clone();
            self.layout.print_preview(&item, y);
        }
        print_pointer(y);
    }

    pub fn go_bottom(&mut self) {
        let len = self.list.len();
        if len == 0 {
            return;
        }
        let visible = self.layout.terminal_row.saturating_sub(STARTING_POINT) as usize;
        self.layout.nums.index = len - 1;
        if len > visible {
            self.layout.nums.skip = (len - visible) as u16;
            let y = self.layout.terminal_row - 2;
            self.redraw(y);
        } else {
            self.layout.nums.skip = 0;
            let y = BEGINNING_ROW + (len as u16) - 1;
            self.redraw(y);
        }
    }

    pub fn half_page_down(&mut self) {
        let len = self.list.len();
        if len == 0 {
            return;
        }
        let half = (self.layout.terminal_row / 2) as usize;
        let visible = self.layout.terminal_row.saturating_sub(STARTING_POINT) as usize;
        let new_index = std::cmp::min(self.layout.nums.index + half, len - 1);
        self.layout.nums.index = new_index;
        if len <= visible {
            self.layout.nums.skip = 0;
            let y = BEGINNING_ROW + new_index as u16;
            self.redraw(y);
        } else {
            let skip = self.layout.nums.skip as usize;
            let scroll_row = self.layout.terminal_row.saturating_sub(5) as usize;
            if new_index >= skip && new_index - skip + (BEGINNING_ROW as usize) < scroll_row {
                let y = (BEGINNING_ROW as usize + new_index - skip) as u16;
                self.redraw(y);
            } else {
                let y_target = scroll_row;
                let new_skip = (new_index + BEGINNING_ROW as usize).saturating_sub(y_target);
                self.layout.nums.skip = new_skip as u16;
                let y = (new_index + BEGINNING_ROW as usize - new_skip) as u16;
                self.redraw(y);
            }
        }
    }

    pub fn half_page_up(&mut self) {
        let len = self.list.len();
        if len == 0 {
            return;
        }
        let half = (self.layout.terminal_row / 2) as usize;
        let visible = self.layout.terminal_row.saturating_sub(STARTING_POINT) as usize;
        let new_index = self.layout.nums.index.saturating_sub(half);
        self.layout.nums.index = new_index;
        if len <= visible {
            self.layout.nums.skip = 0;
            let y = BEGINNING_ROW + new_index as u16;
            self.redraw(y);
        } else {
            let skip = self.layout.nums.skip as usize;
            if new_index >= skip + SCROLL_POINT as usize {
                let y = (BEGINNING_ROW as usize + new_index - skip) as u16;
                self.redraw(y);
            } else {
                let new_skip = new_index.saturating_sub(SCROLL_POINT as usize);
                self.layout.nums.skip = new_skip as u16;
                let y = (BEGINNING_ROW as usize + new_index - new_skip) as u16;
                self.redraw(y);
            }
        }
    }

    /// Enter a directory (via `l`).
    pub fn enter_dir(&mut self, target: &Path, memo_key: &Path) -> Result<(), FxError> {
        let _ = memo_key;
        // save parent memo
        self.p_memo.insert(
            target.to_path_buf(),
            Memo {
                num: self.layout.nums.clone(),
                cursor_pos: self.layout.y,
            },
        );
        std::env::set_current_dir(target)?;
        self.current_dir = target.to_path_buf();
        self.keyword = None;
        self.layout.preview_scroll = 0;
        match self.c_memo.get(target).cloned() {
            Some(memo) => {
                self.layout.nums = memo.num;
                self.update_list()?;
                self.jumplist.add(target);
                self.zoxide_add();
                let y = self.fix_cursor_after_reload(memo.cursor_pos);
                self.redraw(y);
            }
            None => {
                self.layout.nums.reset();
                self.update_list()?;
                self.jumplist.add(target);
                self.zoxide_add();
                self.redraw(BEGINNING_ROW);
            }
        }
        Ok(())
    }

    /// Go to the parent directory (via `h`).
    pub fn go_parent(&mut self) -> Result<(), FxError> {
        let current = self.current_dir.clone();
        let parent = match current.parent() {
            Some(p) => p.to_path_buf(),
            None => return Ok(()),
        };
        self.c_memo.insert(
            current.clone(),
            Memo {
                num: self.layout.nums.clone(),
                cursor_pos: self.layout.y,
            },
        );
        std::env::set_current_dir(&parent)?;
        self.current_dir = parent.clone();
        self.keyword = None;
        self.layout.preview_scroll = 0;
        match self.p_memo.get(&current).cloned() {
            Some(memo) => {
                self.layout.nums = memo.num;
                self.update_list()?;
                self.jumplist.add(&parent);
                self.zoxide_add();
                let y = self.fix_cursor_after_reload(memo.cursor_pos);
                self.redraw(y);
            }
            None => {
                self.layout.nums.reset();
                self.update_list()?;
                self.jumplist.add(&parent);
                self.zoxide_add();
                let child_name = current.file_name().map(|n| n.to_string_lossy().into_owned());
                let found = child_name.and_then(|name| {
                    self.list.iter().position(|x| x.file_name == name)
                });
                match found {
                    Some(index) => {
                        self.layout.nums.index = index;
                        if index > SCROLL_POINT as usize {
                            self.layout.nums.skip = (index - SCROLL_POINT as usize) as u16;
                            self.redraw(BEGINNING_ROW + SCROLL_POINT);
                        } else {
                            self.layout.nums.skip = 0;
                            self.redraw(BEGINNING_ROW + index as u16);
                        }
                    }
                    None => {
                        self.redraw(BEGINNING_ROW);
                    }
                }
            }
        }
        Ok(())
    }

    /// After deleting, keep the index within bounds.
    pub fn adjust_after_delete(&mut self, y: u16) -> u16 {
        let len = self.list.len();
        if len == 0 {
            self.layout.nums.reset();
            return BEGINNING_ROW;
        }
        let mut y = y;
        while self.layout.nums.index >= len {
            self.layout.nums.index -= 1;
            if y > BEGINNING_ROW {
                y -= 1;
            } else if self.layout.nums.skip > 0 {
                self.layout.nums.skip -= 1;
            }
        }
        y
    }

    /// After reloading the list, make sure the index/skip are valid.
    pub fn fix_cursor_after_reload(&mut self, y: u16) -> u16 {
        let len = self.list.len();
        if len == 0 {
            self.layout.nums.reset();
            return BEGINNING_ROW;
        }
        let mut y = y;
        while self.layout.nums.index >= len {
            self.layout.nums.index -= 1;
            if y > BEGINNING_ROW {
                y -= 1;
            } else if self.layout.nums.skip > 0 {
                self.layout.nums.skip -= 1;
            }
        }
        y
    }

    /// Put items from a register and show messages.
    pub fn put_from_register(&mut self, targets: &[ItemBuffer], y: u16) -> Result<(), FxError> {
        let start = Instant::now();
        print_info("PUT: Processing...", y);
        let put = self.put_items(targets, true)?;
        log::info!("PUT: {:?}", put);
        self.reload(y)?;
        let msg = if targets.len() == 1 {
            format!("1 item inserted. {}", duration_to_string(start.elapsed()))
        } else {
            format!(
                "{} items inserted. {}",
                targets.len(),
                duration_to_string(start.elapsed())
            )
        };
        print_info(msg, y);
        Ok(())
    }

    /// Incremental search mode.
    pub fn search_mode(&mut self) -> Result<(), FxError> {
        delete_cursor();
        show_cursor();
        move_to(1, INFO_ROW);
        clear_current_line();
        print("/");
        self.search_input = true;
        let mut chars: Vec<char> = vec![];
        let mut pos = 0usize;
        let saved_nums = self.layout.nums.clone();
        let saved_y = self.layout.y;
        loop {
            if let Event::Key(KeyEvent {
                code, modifiers, ..
            }) = event::read()?
            {
                match code {
                    KeyCode::Esc => {
                        self.search_input = false;
                        self.keyword = None;
                        self.update_matches();
                        self.layout.nums = saved_nums;
                        hide_cursor();
                        self.redraw(saved_y);
                        return Ok(());
                    }
                    KeyCode::Enter => {
                        self.search_input = false;
                        if chars.is_empty() {
                            self.keyword = None;
                        }
                        move_to(1, INFO_ROW);
                        clear_current_line();
                        let y = self.layout.y;
                        self.move_cursor(y);
                        hide_cursor();
                        return Ok(());
                    }
                    KeyCode::Left => {
                        if pos > 0 {
                            pos -= 1;
                            let w = chars[pos].width().unwrap_or(0) as u16;
                            if w > 0 {
                                move_left(w);
                            }
                        }
                    }
                    KeyCode::Right => {
                        if pos < chars.len() {
                            let w = chars[pos].width().unwrap_or(0) as u16;
                            pos += 1;
                            if w > 0 {
                                let _ = execute!(stdout(), MoveRight(w));
                            }
                        }
                    }
                    KeyCode::Backspace => {
                        if pos > 0 {
                            chars.remove(pos - 1);
                            pos -= 1;
                            self.search_update(&chars, pos);
                        }
                    }
                    KeyCode::Char('h') if modifiers.contains(KeyModifiers::CONTROL) => {
                        if pos > 0 {
                            chars.remove(pos - 1);
                            pos -= 1;
                            self.search_update(&chars, pos);
                        }
                    }
                    KeyCode::Char(c) => {
                        if modifiers.contains(KeyModifiers::CONTROL) {
                            continue;
                        }
                        chars.insert(pos, c);
                        pos += 1;
                        self.search_update(&chars, pos);
                    }
                    _ => {}
                }
            }
        }
    }

    fn search_update(&mut self, chars: &[char], pos: usize) {
        let keyword: String = chars.iter().collect();
        self.keyword = if keyword.is_empty() {
            None
        } else {
            Some(keyword.clone())
        };
        self.update_matches();
        let first = self.list.iter().position(|x| x.matches);
        match first {
            Some(index) => {
                self.layout.nums.index = index;
                self.layout.nums.skip = index as u16;
                self.redraw(BEGINNING_ROW);
            }
            None => {
                let y = self.layout.y;
                self.redraw(y);
            }
        }
        move_to(1, INFO_ROW);
        clear_current_line();
        print(&format!("/{}", keyword));
        let before: String = chars[..pos].iter().collect();
        move_to(2 + str_width(&before), INFO_ROW);
    }

    /// Jump to the next (or previous) matching item.
    pub fn search_next(&mut self, backward: bool) {
        if self.keyword.is_none() {
            return;
        }
        let index = self.layout.nums.index;
        let target = if backward {
            self.list[..index]
                .iter()
                .rposition(|x| x.matches)
        } else {
            self.list
                .iter()
                .enumerate()
                .skip(index + 1)
                .find(|(_, x)| x.matches)
                .map(|(i, _)| i)
        };
        if let Some(i) = target {
            self.layout.nums.index = i;
            self.layout.nums.skip = i as u16;
            self.redraw(BEGINNING_ROW);
        }
    }
}

impl Layout {
    /// The full terminal row count (even in horizontal split).
    pub fn terminal_row_full(&self) -> u16 {
        match (self.side, self.split) {
            (Side::None, _) | (_, Split::Vertical) => self.terminal_row,
            (_, Split::Horizontal) => self.preview_start.1 + self.preview_space.1 + 1,
        }
    }
}

pub fn unused_imports_guard() {
    let _ = MoveLeft(1);
    let _ = LeaveAlternateScreen;
}
