//! Minimal tar (ustar/gnu/pax) extraction.
use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};

use crate::errors::FxError;

fn parse_octal(b: &[u8]) -> u64 {
    // GNU base-256 encoding
    if !b.is_empty() && (b[0] & 0x80) != 0 {
        let mut v: u64 = 0;
        for (i, &c) in b.iter().enumerate() {
            let c = if i == 0 { c & 0x7f } else { c };
            v = (v << 8) | c as u64;
        }
        return v;
    }
    let s: String = b
        .iter()
        .take_while(|&&c| c != 0 && c != b' ')
        .map(|&c| c as char)
        .collect();
    let s = s.trim();
    u64::from_str_radix(s, 8).unwrap_or(0)
}

fn cstr(b: &[u8]) -> String {
    let end = b.iter().position(|&c| c == 0).unwrap_or(b.len());
    String::from_utf8_lossy(&b[..end]).into_owned()
}

fn safe_join(dest: &Path, name: &str) -> Option<PathBuf> {
    let mut p = dest.to_path_buf();
    for comp in Path::new(name).components() {
        match comp {
            std::path::Component::Normal(c) => p.push(c),
            std::path::Component::CurDir => {}
            _ => return None,
        }
    }
    Some(p)
}

pub fn unpack_tar(bytes: &[u8], dest: &Path) -> Result<(), FxError> {
    fs::create_dir_all(dest)?;
    let mut pos = 0usize;
    let mut long_name: Option<String> = None;
    let mut long_link: Option<String> = None;
    let mut pax_path: Option<String> = None;
    let mut pax_link: Option<String> = None;
    while pos + 512 <= bytes.len() {
        let header = &bytes[pos..pos + 512];
        if header.iter().all(|&c| c == 0) {
            break;
        }
        let name = cstr(&header[0..100]);
        let mode = parse_octal(&header[100..108]) as u32;
        let size = parse_octal(&header[124..136]) as usize;
        let typeflag = header[156];
        let linkname = cstr(&header[157..257]);
        let magic = &header[257..263];
        let prefix = if magic.starts_with(b"ustar") && !magic.starts_with(b"ustar ") {
            cstr(&header[345..500])
        } else {
            String::new()
        };
        pos += 512;
        let data_end = std::cmp::min(pos + size, bytes.len());
        let data = &bytes[pos..data_end];
        let blocks = (size + 511) / 512;
        pos += blocks * 512;

        match typeflag {
            b'L' => {
                long_name = Some(cstr(data));
                continue;
            }
            b'K' => {
                long_link = Some(cstr(data));
                continue;
            }
            b'x' => {
                // pax extended header
                let s = String::from_utf8_lossy(data).into_owned();
                let mut rest = s.as_str();
                while !rest.is_empty() {
                    let sp = match rest.find(' ') {
                        Some(i) => i,
                        None => break,
                    };
                    let len: usize = match rest[..sp].trim().parse() {
                        Ok(l) => l,
                        Err(_) => break,
                    };
                    if len == 0 || len > rest.len() {
                        break;
                    }
                    let record = &rest[sp + 1..len];
                    if let Some(eq) = record.find('=') {
                        let key = &record[..eq];
                        let val = record[eq + 1..].trim_end_matches('\n');
                        match key {
                            "path" => pax_path = Some(val.to_owned()),
                            "linkpath" => pax_link = Some(val.to_owned()),
                            _ => {}
                        }
                    }
                    rest = &rest[len..];
                }
                continue;
            }
            b'g' => continue,
            _ => {}
        }

        let full_name = if let Some(p) = pax_path.take() {
            p
        } else if let Some(l) = long_name.take() {
            l
        } else if !prefix.is_empty() {
            format!("{}/{}", prefix, name)
        } else {
            name
        };
        let link_target = if let Some(l) = pax_link.take() {
            l
        } else if let Some(l) = long_link.take() {
            l
        } else {
            linkname
        };
        let target = match safe_join(dest, &full_name) {
            Some(t) => t,
            None => continue,
        };
        match typeflag {
            b'5' => {
                fs::create_dir_all(&target)?;
                let _ = fs::set_permissions(&target, fs::Permissions::from_mode(mode & 0o7777));
            }
            b'0' | b'\0' | b'7' => {
                if let Some(parent) = target.parent() {
                    fs::create_dir_all(parent)?;
                }
                fs::write(&target, data)?;
                let _ = fs::set_permissions(&target, fs::Permissions::from_mode(mode & 0o7777));
            }
            b'2' => {
                if let Some(parent) = target.parent() {
                    fs::create_dir_all(parent)?;
                }
                let _ = fs::remove_file(&target);
                std::os::unix::fs::symlink(&link_target, &target)?;
            }
            b'1' => {
                if let Some(parent) = target.parent() {
                    fs::create_dir_all(parent)?;
                }
                if let Some(src) = safe_join(dest, &link_target) {
                    let _ = fs::hard_link(&src, &target);
                }
            }
            _ => {}
        }
    }
    Ok(())
}
