            String::new()
        };
        pos += 512;
        let data_end = std::cmp::min(pos + size, bytes.len());
        let data = &bytes[pos..data_end];
        let blocks = (size + 511) / 512;
        pos += blocks * 512;

        match typeflag {
            b'L' => {
                long_name = Some(cstr(data));
                continue;
            }
            b'K' => {
                long_link = Some(cstr(data));
                continue;
            }
            b'x' => {
                // pax extended header
                let s = String::from_utf8_lossy(data).into_owned();
                let mut rest = s.as_str();
                while !rest.is_empty() {
                    let sp = match rest.find(' ') {
                        Some(i) => i,
                        None => break,
                    };
                    let len: usize = match rest[..sp].trim().parse() {
                        Ok(l) => l,
                        Err(_) => break,
                    };
                    if len == 0 || len > rest.len() {
                        break;
                    }
                    let record = &rest[sp + 1..len];
                    if let Some(eq) = record.find('=') {
                        let key = &record[..eq];
                        let val = record[eq + 1..].trim_end_matches('\n');
                        match key {
                            "path" => pax_path = Some(val.to_owned()),
                            "linkpath" => pax_link = Some(val.to_owned()),
                            _ => {}
                        }
                    }
                    rest = &rest[len..];
                }
                continue;
            }
            b'g' => continue,
            _ => {}
        }

        let full_name = if let Some(p) = pax_path.take() {
            p
        } else if let Some(l) = long_name.take() {
            l
        } else if !prefix.is_empty() {
            format!("{}/{}", prefix, name)
        } else {
            name
        };
        let link_target = if let Some(l) = pax_link.take() {
            l
        } else if let Some(l) = long_link.take() {
            l
        } else {
            linkname
        };
        let target = match safe_join(dest, &full_name) {
            Some(t) => t,
            None => continue,
        };
        match typeflag {
            b'5' => {
                fs::create_dir_all(&target)?;
                let _ = fs::set_permissions(&target, fs::Permissions::from_mode(mode & 0o7777));
            }
            b'0' | b'\0' | b'7' => {
                if let Some(parent) = target.parent() {
                    fs::create_dir_all(parent)?;
                }
                fs::write(&target, data)?;
                let _ = fs::set_permissions(&target, fs::Permissions::from_mode(mode & 0o7777));
            }
            b'2' => {
                if let Some(parent) = target.parent() {
                    fs::create_dir_all(parent)?;
                }
                let _ = fs::remove_file(&target);
                std::os::unix::fs::symlink(&link_target, &target)?;
            }
            b'1' => {
                if let Some(parent) = target.parent() {
                    fs::create_dir_all(parent)?;
                }
                if let Some(src) = safe_join(dest, &link_target) {
                    let _ = fs::hard_link(&src, &target);
                }
            }
            _ => {}
        }
    }
    Ok(())
}
