//! bzip2 decompression (pure Rust implementation of the bzip2 format).

struct BitReader<'a> {
    data: &'a [u8],
    pos: usize,
    bit: u32,
    nbits: u32,
}

impl<'a> BitReader<'a> {
    fn new(data: &'a [u8]) -> Self {
        BitReader {
            data,
            pos: 0,
            bit: 0,
            nbits: 0,
        }
    }
    fn read(&mut self, n: u32) -> Result<u32, String> {
        while self.nbits < n {
            if self.pos >= self.data.len() {
                return Err("unexpected end of bzip2 data".to_owned());
            }
            self.bit = (self.bit << 8) | self.data[self.pos] as u32;
            self.pos += 1;
            self.nbits += 8;
        }
        let v = (self.bit >> (self.nbits - n)) & ((1u64 << n) as u32).wrapping_sub(1);
        self.nbits -= n;
        self.bit &= (1u32 << self.nbits).wrapping_sub(1);
        Ok(v)
    }
    fn read_bit(&mut self) -> Result<bool, String> {
        Ok(self.read(1)? == 1)
    }
}

struct Huffman {
    limit: [i32; 21],
    base: [i32; 21],
    perm: Vec<u16>,
    min_len: u32,
    max_len: u32,
}

fn build_huffman(lengths: &[u8]) -> Result<Huffman, String> {
    let min_len = *lengths.iter().min().unwrap() as u32;
    let max_len = *lengths.iter().max().unwrap() as u32;
    if min_len < 1 || max_len > 20 {
        return Err("invalid huffman code lengths".to_owned());
    }
    let mut perm = Vec::with_capacity(lengths.len());
    for len in min_len..=max_len {
        for (i, &l) in lengths.iter().enumerate() {
            if l as u32 == len {
                perm.push(i as u16);
            }
        }
    }
    let mut count = [0i32; 21];
    for &l in lengths {
        count[l as usize] += 1;
    }
    let mut limit = [0i32; 21];
    let mut base = [0i32; 21];
    let mut code: i32 = 0;
    let mut idx: i32 = 0;
    for len in min_len..=max_len {
        let l = len as usize;
        base[l] = code - idx;
        code += count[l];
        idx += count[l];
        limit[l] = code - 1;
        code <<= 1;
    }
    Ok(Huffman {
        limit,
        base,
        perm,
        min_len,
        max_len,
    })
}

fn decode_symbol(br: &mut BitReader, h: &Huffman) -> Result<u16, String> {
    let mut len = h.min_len;
    let mut code = br.read(len)? as i32;
    loop {
        if code <= h.limit[len as usize] {
            let idx = code - h.base[len as usize];
            if idx < 0 || idx as usize >= h.perm.len() {
                return Err("invalid huffman code".to_owned());
            }
            return Ok(h.perm[idx as usize]);
        }
        len += 1;
        if len > h.max_len {
            return Err("invalid huffman code".to_owned());
        }
        code = (code << 1) | br.read(1)? as i32;
    }
}

pub fn decompress(data: &[u8]) -> Result<Vec<u8>, String> {
    if data.len() < 4 || &data[0..2] != b"BZ" || data[2] != b'h' {
        return Err("invalid bzip2 header".to_owned());
    }
    let level = data[3];
    if !(b'1'..=b'9').contains(&level) {
        return Err("invalid bzip2 block size".to_owned());
    }
    let block_max = (level - b'0') as usize * 100_000;
    let mut br = BitReader::new(&data[4..]);
    let mut out: Vec<u8> = Vec::new();
    loop {
        let magic_hi = br.read(24)? as u64;
        let magic_lo = br.read(24)? as u64;
        let magic = (magic_hi << 24) | magic_lo;
        if magic == 0x177245385090 {
            // end of stream: combined CRC
            let _crc = br.read(32)?;
            // check for another stream (concatenated)
            // align to byte
            let _ = br.nbits;
            break;
        }
        if magic != 0x314159265359 {
            return Err("invalid bzip2 block magic".to_owned());
        }
        let _block_crc = br.read(32)?;
        let randomized = br.read_bit()?;
        if randomized {
            return Err("randomized bzip2 blocks are not supported".to_owned());
        }
        let orig_ptr = br.read(24)? as usize;

        // symbol map
        let used_groups = br.read(16)?;
        let mut seq_to_unseq: Vec<u8> = Vec::new();
        for i in 0..16 {
            if used_groups & (1 << (15 - i)) != 0 {
                let used = br.read(16)?;
                for j in 0..16 {
                    if used & (1 << (15 - j)) != 0 {
                        seq_to_unseq.push((i * 16 + j) as u8);
                    }
                }
            }
        }
        if seq_to_unseq.is_empty() {
            return Err("invalid bzip2 symbol map".to_owned());
        }
        let alpha_size = seq_to_unseq.len() + 2;

        let n_groups = br.read(3)? as usize;
        if !(2..=6).contains(&n_groups) {
            return Err("invalid bzip2 group count".to_owned());
        }
        let n_selectors = br.read(15)? as usize;
        if n_selectors == 0 {
            return Err("invalid bzip2 selector count".to_owned());
        }
        let mut selectors_mtf = Vec::with_capacity(n_selectors);
        for _ in 0..n_selectors {
            let mut j = 0u8;
            while br.read_bit()? {
                j += 1;
                if j as usize >= n_groups {
                    return Err("invalid bzip2 selector".to_owned());
                }
            }
            selectors_mtf.push(j);
        }
        // MTF decode selectors
        let mut pos: Vec<u8> = (0..n_groups as u8).collect();
        let mut selectors = Vec::with_capacity(n_selectors);
        for &v in &selectors_mtf {
            let v = v as usize;
            let tmp = pos[v];
            for k in (1..=v).rev() {
                pos[k] = pos[k - 1];
            }
            pos[0] = tmp;
            selectors.push(tmp);
        }

        // coding tables
        let mut tables = Vec::with_capacity(n_groups);
        for _ in 0..n_groups {
            let mut lengths = vec![0u8; alpha_size];
            let mut curr = br.read(5)? as i32;
            for l in lengths.iter_mut() {
                loop {
                    if !(1..=20).contains(&curr) {
                        return Err("invalid bzip2 code length".to_owned());
                    }
                    if !br.read_bit()? {
                        break;
                    }
                    if br.read_bit()? {
                        curr -= 1;
                    } else {
                        curr += 1;
                    }
                }
                *l = curr as u8;
            }
            tables.push(build_huffman(&lengths)?);
        }

        // decode MTF/RLE2 symbols
        let eob = alpha_size as u16 - 1;
        let mut mtf: Vec<u8> = (0..seq_to_unseq.len() as u8).collect();
        let mut tt: Vec<u32> = Vec::with_capacity(block_max);
        let mut unzftab = [0u32; 256];
        let mut group_no: usize = 0;
        let mut group_pos = 0;
        let mut run_len: usize = 0;
        let mut run_weight: usize = 1;
        let mut have_run = false;
        loop {
            if group_pos == 0 {
                if group_no >= selectors.len() {
                    return Err("bzip2 selector overflow".to_owned());
                }
                group_pos = 50;
                group_no += 1;
            }
            group_pos -= 1;
            let table = &tables[selectors[group_no - 1] as usize];
            let sym = decode_symbol(&mut br, table)?;
            if sym == 0 || sym == 1 {
                // RUNA / RUNB
                if !have_run {
                    run_len = 0;
                    run_weight = 1;
                    have_run = true;
                }
                if sym == 0 {
                    run_len += run_weight;
                } else {
                    run_len += 2 * run_weight;
                }
                run_weight <<= 1;
                if run_len > block_max {
                    return Err("bzip2 run too long".to_owned());
                }
                continue;
            }
            if have_run {
                let b = seq_to_unseq[mtf[0] as usize];
                if tt.len() + run_len > block_max {
                    return Err("bzip2 block overflow".to_owned());
                }
                unzftab[b as usize] += run_len as u32;
                for _ in 0..run_len {
                    tt.push(b as u32);
                }
                have_run = false;
            }
            if sym == eob {
                break;
            }
            // MTF value
            let idx = (sym - 1) as usize;
            if idx >= mtf.len() {
                return Err("invalid bzip2 mtf index".to_owned());
            }
            let v = mtf[idx];
            for k in (1..=idx).rev() {
                mtf[k] = mtf[k - 1];
            }
            mtf[0] = v;
            let b = seq_to_unseq[v as usize];
            if tt.len() >= block_max {
                return Err("bzip2 block overflow".to_owned());
            }
            unzftab[b as usize] += 1;
            tt.push(b as u32);
        }
        if orig_ptr >= tt.len().max(1) {
            if tt.is_empty() {
                continue;
            }
            return Err("invalid bzip2 origPtr".to_owned());
        }
        // inverse BWT
        let n = tt.len();
        let mut cftab = [0u32; 257];
        for i in 0..256 {
            cftab[i + 1] = cftab[i] + unzftab[i];
        }
        let mut cftab_run = cftab;
        for i in 0..n {
            let b = (tt[i] & 0xff) as usize;
            let dst = cftab_run[b] as usize;
            cftab_run[b] += 1;
            tt[dst] |= (i as u32) << 8;
        }
        // RLE1 decode while walking
        let mut t_pos = tt[orig_ptr] >> 8;
        let mut last: i32 = -1;
        let mut count = 0;
        let mut remaining = n;
        while remaining > 0 {
            let entry = tt[t_pos as usize];
            let b = (entry & 0xff) as u8;
            t_pos = entry >> 8;
            remaining -= 1;
            if count == 4 {
                for _ in 0..b {
                    out.push(last as u8);
                }
                count = 0;
                last = -1;
                continue;
            }
            if b as i32 == last {
                count += 1;
            } else {
                count = 1;
                last = b as i32;
            }
            out.push(b);
        }
    }
    Ok(out)
}
