//! xz / LZMA2 / LZMA decompression (pure Rust).

const EOF_ERR: &str =
    "IoError(Error { kind: UnexpectedEof, message: \"failed to fill whole buffer\" })";

struct Cursor<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> Cursor<'a> {
    fn u8(&mut self) -> Result<u8, String> {
        if self.pos >= self.data.len() {
            return Err(EOF_ERR.to_owned());
        }
        let b = self.data[self.pos];
        self.pos += 1;
        Ok(b)
    }
    fn bytes(&mut self, n: usize) -> Result<&'a [u8], String> {
        if self.pos + n > self.data.len() {
            return Err(EOF_ERR.to_owned());
        }
        let s = &self.data[self.pos..self.pos + n];
        self.pos += n;
        Ok(s)
    }
    fn vli(&mut self) -> Result<u64, String> {
        let mut result: u64 = 0;
        for i in 0..9 {
            let b = self.u8()?;
            result |= ((b & 0x7f) as u64) << (7 * i);
            if b & 0x80 == 0 {
                return Ok(result);
            }
        }
        Err("XzError(\"invalid VLI\")".to_owned())
    }
}

// ---------------- range decoder ----------------

struct RangeDecoder<'a> {
    data: &'a [u8],
    pos: usize,
    range: u32,
    code: u32,
}

impl<'a> RangeDecoder<'a> {
    fn new(data: &'a [u8]) -> Result<Self, String> {
        if data.len() < 5 {
            return Err(EOF_ERR.to_owned());
        }
        if data[0] != 0 {
            return Err("LzmaError(\"Invalid range coder init\")".to_owned());
        }
        let code = u32::from_be_bytes([data[1], data[2], data[3], data[4]]);
        Ok(RangeDecoder {
            data,
            pos: 5,
            range: 0xFFFF_FFFF,
            code,
        })
    }
    #[inline]
    fn next_byte(&mut self) -> u8 {
        if self.pos < self.data.len() {
            let b = self.data[self.pos];
            self.pos += 1;
            b
        } else {
            self.pos += 1;
            0
        }
    }
    #[inline]
    fn normalize(&mut self) {
        if self.range < 0x0100_0000 {
            self.range <<= 8;
            self.code = (self.code << 8) | self.next_byte() as u32;
        }
    }
    #[inline]
    fn bit(&mut self, prob: &mut u16) -> u32 {
        let bound = (self.range >> 11) * (*prob as u32);
        let bit;
        if self.code < bound {
            self.range = bound;
            *prob += (2048 - *prob) >> 5;
            bit = 0;
        } else {
            self.range -= bound;
            self.code -= bound;
            *prob -= *prob >> 5;
            bit = 1;
        }
        self.normalize();
        bit
    }
    fn direct_bits(&mut self, n: u32) -> u32 {
        let mut res: u32 = 0;
        for _ in 0..n {
            self.range >>= 1;
            self.code = self.code.wrapping_sub(self.range);
            let t = 0u32.wrapping_sub(self.code >> 31);
            self.code = self.code.wrapping_add(self.range & t);
            self.normalize();
            res = (res << 1).wrapping_add(t.wrapping_add(1));
        }
        res
    }
    fn bittree(&mut self, probs: &mut [u16], num_bits: u32) -> u32 {
        let mut m: u32 = 1;
        for _ in 0..num_bits {
            m = (m << 1) + self.bit(&mut probs[m as usize]);
        }
        m - (1 << num_bits)
    }
    fn bittree_reverse(&mut self, probs: &mut [u16], num_bits: u32) -> u32 {
        let mut m: u32 = 1;
        let mut sym: u32 = 0;
        for i in 0..num_bits {
            let bit = self.bit(&mut probs[m as usize]);
            m = (m << 1) + bit;
            sym |= bit << i;
        }
        sym
    }
    fn is_finished_ok(&self) -> bool {
        self.code == 0
    }
}

// ---------------- LZMA decoder state ----------------

const PROB_INIT: u16 = 1024;
const NUM_STATES: usize = 12;
const POS_STATES_MAX: usize = 16;
const LEN_LOW_BITS: u32 = 3;
const LEN_MID_BITS: u32 = 3;
const LEN_HIGH_BITS: u32 = 8;
const END_POS_MODEL_INDEX: u32 = 14;
const NUM_FULL_DISTANCES: usize = 128;
const ALIGN_BITS: u32 = 4;

struct LenDecoder {
    choice: u16,
    choice2: u16,
    low: Vec<u16>,  // POS_STATES_MAX * 8
    mid: Vec<u16>,  // POS_STATES_MAX * 8
    high: Vec<u16>, // 256
}

impl LenDecoder {
    fn new() -> Self {
        LenDecoder {
            choice: PROB_INIT,
            choice2: PROB_INIT,
            low: vec![PROB_INIT; POS_STATES_MAX << LEN_LOW_BITS],
            mid: vec![PROB_INIT; POS_STATES_MAX << LEN_MID_BITS],
            high: vec![PROB_INIT; 1 << LEN_HIGH_BITS],
        }
    }
    fn decode(&mut self, rc: &mut RangeDecoder, pos_state: usize) -> u32 {
        if rc.bit(&mut self.choice) == 0 {
            let s = pos_state << LEN_LOW_BITS;
            return rc.bittree(&mut self.low[s..s + 8], LEN_LOW_BITS);
        }
        if rc.bit(&mut self.choice2) == 0 {
            let s = pos_state << LEN_MID_BITS;
            return 8 + rc.bittree(&mut self.mid[s..s + 8], LEN_MID_BITS);
        }
        16 + rc.bittree(&mut self.high, LEN_HIGH_BITS)
    }
}

struct LzmaState {
    lc: u32,
    lp: u32,
    pb: u32,
    literal: Vec<u16>,
    pos_slot: Vec<u16>, // 4 * 64
    pos_decoders: Vec<u16>,
    align: Vec<u16>,
    len_dec: LenDecoder,
    rep_len_dec: LenDecoder,
    is_match: Vec<u16>,
    is_rep: Vec<u16>,
    is_rep_g0: Vec<u16>,
    is_rep_g1: Vec<u16>,
    is_rep_g2: Vec<u16>,
    is_rep0_long: Vec<u16>,
    state: usize,
    rep: [u32; 4],
}

impl LzmaState {
    fn new(lc: u32, lp: u32, pb: u32) -> Self {
        LzmaState {
            lc,
            lp,
            pb,
            literal: vec![PROB_INIT; 0x300 << (lc + lp)],
            pos_slot: vec![PROB_INIT; 4 * 64],
            pos_decoders: vec![PROB_INIT; 1 + NUM_FULL_DISTANCES - END_POS_MODEL_INDEX as usize],
            align: vec![PROB_INIT; 1 << ALIGN_BITS],
            len_dec: LenDecoder::new(),
            rep_len_dec: LenDecoder::new(),
            is_match: vec![PROB_INIT; NUM_STATES * POS_STATES_MAX],
            is_rep: vec![PROB_INIT; NUM_STATES],
            is_rep_g0: vec![PROB_INIT; NUM_STATES],
            is_rep_g1: vec![PROB_INIT; NUM_STATES],
            is_rep_g2: vec![PROB_INIT; NUM_STATES],
            is_rep0_long: vec![PROB_INIT; NUM_STATES * POS_STATES_MAX],
            state: 0,
            rep: [0; 4],
        }
    }

    fn reset_state(&mut self) {
        let (lc, lp, pb) = (self.lc, self.lp, self.pb);
        *self = LzmaState::new(lc, lp, pb);
    }

    fn decode_distance(&mut self, rc: &mut RangeDecoder, len: u32) -> u32 {
        let len_state = std::cmp::min(len, 3) as usize;
        let s = len_state * 64;
        let pos_slot = rc.bittree(&mut self.pos_slot[s..s + 64], 6);
        if pos_slot < 4 {
            return pos_slot;
        }
        let num_direct_bits = (pos_slot >> 1) - 1;
        let mut dist = (2 | (pos_slot & 1)) << num_direct_bits;
        if pos_slot < END_POS_MODEL_INDEX {
            let base = (dist - pos_slot) as usize;
            let end = base + (1 << num_direct_bits) as usize;
            let end = std::cmp::min(end, self.pos_decoders.len());
            dist += rc.bittree_reverse(&mut self.pos_decoders[base..end], num_direct_bits);
        } else {
            dist += rc.direct_bits(num_direct_bits - ALIGN_BITS) << ALIGN_BITS;
            dist += rc.bittree_reverse(&mut self.align, ALIGN_BITS);
        }
        dist
    }

    /// Decode LZMA data into `out` until `unpacked` bytes have been produced
    /// (or the end marker is hit if `unpacked` is None).
    fn decode(
        &mut self,
        rc: &mut RangeDecoder,
        out: &mut Vec<u8>,
        dict_start: usize,
        unpacked: Option<usize>,
    ) -> Result<(), String> {
        let target = unpacked.map(|u| out.len() + u);
        let pb_mask = (1usize << self.pb) - 1;
        let lp_mask = (1usize << self.lp) - 1;
        loop {
            if let Some(t) = target {
                if out.len() >= t {
                    break;
                }
            }
            let pos_state = out.len() & pb_mask;
            let s = self.state;
            if rc.bit(&mut self.is_match[(s << 4) + pos_state]) == 0 {
                // literal
                let prev_byte = if out.len() > dict_start {
                    out[out.len() - 1] as usize
                } else {
                    0
                };
                let lit_state = ((out.len() & lp_mask) << self.lc) + (prev_byte >> (8 - self.lc));
                let base = 0x300 * lit_state;
                let probs = &mut self.literal[base..base + 0x300];
                let mut symbol: usize = 1;
                if s >= 7 {
                    let dist = self.rep[0] as usize + 1;
                    if dist > out.len() - dict_start {
                        return Err("LzmaError(\"match distance out of range\")".to_owned());
                    }
                    let mut match_byte = out[out.len() - dist] as usize;
                    loop {
                        let match_bit = (match_byte >> 7) & 1;
                        match_byte <<= 1;
                        let bit = rc.bit(&mut probs[((1 + match_bit) << 8) + symbol]) as usize;
                        symbol = (symbol << 1) | bit;
                        if match_bit != bit {
                            break;
                        }
                        if symbol >= 0x100 {
                            break;
                        }
                    }
                }
                while symbol < 0x100 {
                    symbol = (symbol << 1) | rc.bit(&mut probs[symbol]) as usize;
                }
                out.push((symbol - 0x100) as u8);
                self.state = if s < 4 {
                    0
                } else if s < 10 {
                    s - 3
                } else {
                    s - 6
                };
                continue;
            }
            let len;
            if rc.bit(&mut self.is_rep[s]) == 0 {
                // simple match
                self.rep[3] = self.rep[2];
                self.rep[2] = self.rep[1];
                self.rep[1] = self.rep[0];
                len = self.len_dec.decode(rc, pos_state);
                self.state = if s < 7 { 7 } else { 10 };
                let dist = self.decode_distance(rc, len);
                if dist == 0xFFFF_FFFF {
                    // end marker
                    if rc.is_finished_ok() {
                        break;
                    }
                    return Err("LzmaError(\"invalid end marker\")".to_owned());
                }
                self.rep[0] = dist;
            } else {
                if rc.bit(&mut self.is_rep_g0[s]) == 0 {
                    if rc.bit(&mut self.is_rep0_long[(s << 4) + pos_state]) == 0 {
                        // short rep
                        self.state = if s < 7 { 9 } else { 11 };
                        let dist = self.rep[0] as usize + 1;
                        if dist > out.len() - dict_start {
                            return Err("LzmaError(\"match distance out of range\")".to_owned());
                        }
                        let b = out[out.len() - dist];
                        out.push(b);
                        continue;
                    }
                } else {
                    let dist;
                    if rc.bit(&mut self.is_rep_g1[s]) == 0 {
                        dist = self.rep[1];
                    } else {
                        if rc.bit(&mut self.is_rep_g2[s]) == 0 {
                            dist = self.rep[2];
                        } else {
                            dist = self.rep[3];
                            self.rep[3] = self.rep[2];
                        }
                        self.rep[2] = self.rep[1];
                    }
                    self.rep[1] = self.rep[0];
                    self.rep[0] = dist;
                }
                len = self.rep_len_dec.decode(rc, pos_state);
                self.state = if s < 7 { 8 } else { 11 };
            }
            // copy match
            let mut copy_len = (len + 2) as usize;
            if let Some(t) = target {
                let remain = t - out.len();
                if copy_len > remain {
                    copy_len = remain;
                }
            }
            let dist = self.rep[0] as usize + 1;
            if dist > out.len() - dict_start {
                return Err("LzmaError(\"match distance out of range\")".to_owned());
            }
            for _ in 0..copy_len {
                let b = out[out.len() - dist];
                out.push(b);
            }
        }
        Ok(())
    }
}

fn parse_props(props: u8) -> Result<(u32, u32, u32), String> {
    if props >= 9 * 5 * 5 {
        return Err("LzmaError(\"invalid properties\")".to_owned());
    }
    let lc = (props % 9) as u32;
    let rest = props / 9;
    let lp = (rest % 5) as u32;
    let pb = (rest / 5) as u32;
    Ok((lc, lp, pb))
}

/// Decode an LZMA2 stream. Returns the number of input bytes consumed.
pub fn lzma2_decode(data: &[u8], out: &mut Vec<u8>) -> Result<usize, String> {
    let mut cur = Cursor { data, pos: 0 };
    let mut state: Option<LzmaState> = None;
    let mut dict_start = out.len();
    loop {
        let control = cur.u8()?;
        if control == 0x00 {
            return Ok(cur.pos);
        }
        if control == 0x01 || control == 0x02 {
            if control == 0x01 {
                dict_start = out.len();
            }
            let size = ((cur.u8()? as usize) << 8 | cur.u8()? as usize) + 1;
            let chunk = cur.bytes(size)?;
            out.extend_from_slice(chunk);
            continue;
        }
        if control < 0x80 {
            return Err("LzmaError(\"invalid LZMA2 control byte\")".to_owned());
        }
        let unpacked = (((control & 0x1f) as usize) << 16)
            + (((cur.u8()? as usize) << 8) | cur.u8()? as usize)
            + 1;
        let packed = (((cur.u8()? as usize) << 8) | cur.u8()? as usize) + 1;
        let reset = (control >> 5) & 3;
        if reset >= 2 {
            let props = cur.u8()?;
            let (lc, lp, pb) = parse_props(props)?;
            if lc + lp > 4 {
                return Err("LzmaError(\"invalid lc/lp\")".to_owned());
            }
            state = Some(LzmaState::new(lc, lp, pb));
        } else if reset == 1 {
            match state.as_mut() {
                Some(s) => s.reset_state(),
                None => return Err("LzmaError(\"missing LZMA2 properties\")".to_owned()),
            }
        }
        if reset == 3 {
            dict_start = out.len();
        }
        let st = match state.as_mut() {
            Some(s) => s,
            None => return Err("LzmaError(\"missing LZMA2 properties\")".to_owned()),
        };
        let chunk = cur.bytes(packed)?;
        let mut rc = RangeDecoder::new(chunk)?;
        st.decode(&mut rc, out, dict_start, Some(unpacked))?;
    }
}

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256u32 {
        let mut c = i;
        for _ in 0..8 {
            c = if c & 1 != 0 { 0xEDB8_8320 ^ (c >> 1) } else { c >> 1 };
        }
        table[i as usize] = c;
    }
    let mut crc = 0xFFFF_FFFFu32;
    for &b in data {
        crc = table[((crc ^ b as u32) & 0xff) as usize] ^ (crc >> 8);
    }
    crc ^ 0xFFFF_FFFF
}

/// Decompress an xz container.
pub fn xz_decompress(data: &[u8]) -> Result<Vec<u8>, String> {
    let mut out = Vec::new();
    let mut cur = Cursor { data, pos: 0 };
    loop {
        // stream header
        let header = cur.bytes(12)?;
        if &header[0..6] != b"\xfd7zXZ\x00" {
            return Err("XzError(\"invalid stream header magic\")".to_owned());
        }
        let flags = &header[6..8];
        if flags[0] != 0 {
            return Err("XzError(\"invalid stream flags\")".to_owned());
        }
        let check_type = flags[1] & 0x0f;
        let check_size = match check_type {
            0 => 0,
            1 => 4,
            4 => 8,
            10 => 32,
            _ => return Err("XzError(\"unsupported check type\")".to_owned()),
        };
        let crc = u32::from_le_bytes([header[8], header[9], header[10], header[11]]);
        if crc32(flags) != crc {
            return Err("XzError(\"stream header CRC mismatch\")".to_owned());
        }
        // blocks
        loop {
            let first = cur.u8()?;
            if first == 0 {
                // index
                let num_records = cur.vli()?;
                for _ in 0..num_records {
                    cur.vli()?;
                    cur.vli()?;
                }
                // padding to 4
                while cur.pos % 4 != 0 {
                    cur.u8()?;
                }
                cur.bytes(4)?; // index CRC
                break;
            }
            let header_size = (first as usize + 1) * 4;
            let header_body = cur.bytes(header_size - 1)?;
            let bflags = header_body[0];
            let num_filters = (bflags & 0x03) as usize + 1;
            let mut hc = Cursor {
                data: &header_body[1..header_size - 4 - 1 + 1],
                pos: 0,
            };
            let _compressed_size = if bflags & 0x40 != 0 { Some(hc.vli()?) } else { None };
            let _uncompressed_size = if bflags & 0x80 != 0 { Some(hc.vli()?) } else { None };
            let mut filters = vec![];
            for _ in 0..num_filters {
                let id = hc.vli()?;
                let props_size = hc.vli()? as usize;
                let props = hc.bytes(props_size)?;
                filters.push((id, props.to_vec()));
            }
            if filters.len() != 1 || filters[0].0 != 0x21 {
                return Err("XzError(\"unsupported filter\")".to_owned());
            }
            // block data (LZMA2)
            let block_start = cur.pos;
            let consumed = lzma2_decode(&data[cur.pos..], &mut out)?;
            cur.pos += consumed;
            // block padding
            let compressed_len = cur.pos - block_start;
            let pad = (4 - compressed_len % 4) % 4;
            cur.bytes(pad)?;
            cur.bytes(check_size)?;
        }
        // stream footer
        cur.bytes(12)?;
        // stream padding (multiple of 4 zero bytes) / possible next stream
        while cur.pos < data.len() {
            if data.len() - cur.pos >= 4 && &data[cur.pos..cur.pos + 4] == b"\0\0\0\0" {
                cur.pos += 4;
            } else {
                break;
            }
        }
        if cur.pos >= data.len() {
            break;
        }
    }
    Ok(out)
}
