/// Register entries for deleted items (original names, trash paths).
fn trash_buffers_pre(targets: &[ItemBuffer], trash: &[PathBuf]) -> Vec<ItemBuffer> {
    let mut result = vec![];
    let mut ti = trash.iter().peekable();
    for t in targets {
        let matches_next = ti.peek().map_or(false, |tp| {
            tp.file_name()
                .map(|n| n.to_string_lossy().ends_with(&format!("_{}", t.file_name)))
                .unwrap_or(false)
        });
        if !matches_next {
            // no trash entry for this target (e.g. broken symlink)
            continue;
        }
        let tp = ti.next().unwrap();
        let file_type = if t.file_type == FileType::Symlink {
            FileType::File
        } else {
            t.file_type
        };
        result.push(ItemBuffer {
            file_type,
            file_name: t.file_name.clone(),
            file_path: tp.clone(),
        });
    }
    result
}
